_SDR_JS = """
(function(){
  var RANK_SETTINGS = __RANK_JSON__;
  var COURSE_LENGTH = __COURSE_LENGTH__;
  var SIGNED_IN = __SIGNED_IN__;
  var PX_PER_UNIT = 1.1;
  var CHANNEL_TOP = 0.60, CHANNEL_BOTTOM = 0.93;
  var BOAT_X_FRAC = 0.24;
  var WHALE_X_FRAC = 0.62;  // fixed screen point (was CSS left:62%; JS now positions Y too)
  var HITBOX_X_UNITS = 15, HITBOX_LANE_FRAC = 0.085;
  var GRACE_MS = 1200;
  var STEER_KEY_RATE = 1.0;
  var BOAT_LERP = 8;
  // Rowboat propulsion — boat-specific, not rank-tuned (rank still governs
  // obstacle density/gust coverage/hit-tolerance identically for both
  // boats; only forward-speed physics differ by boat). Each completed
  // press-and-release of Space (or the mobile row button — see row(),
  // which fires on release, not press) adds a burst to rowMomentum, which
  // decays continuously (dm/dt = -ROW_DECAY_PER_SEC*m) rather than stepping
  // down, so it reads as "coasting to a stop" instead of an abrupt cutoff.
  // Requiring release (not just holding the key/button down) is deliberate,
  // per design-review feedback — it forces a distinct stroke gesture that
  // competes for attention with steering, rather than a hold-to-win button.
  // TUNABLE — first-pass values, not yet playtested; flagged in the PR
  // description for a balance pass. Chosen so a single stroke immediately,
  // dramatically exceeds every rank's sailboat drift_speed (10-20 u/s, see
  // _GAME_RANK_DEFAULTS) — "fast off the line" — while a sustainable
  // stroke cadence (roughly one per 1.5s, realistic given each stroke is a
  // deliberate press-and-release, not a held button) still averages out
  // below the sailboat's typical run speed (~26-29 u/s once its ramp + gust
  // bonus are folded in) — "fades over the long haul".
  var ROW_BURST_ADD = 46;        // u/s added to momentum per completed stroke
  var ROW_MAX_MOMENTUM = 145;    // cap so mashing can't run away
  var ROW_DECAY_PER_SEC = 1.6;   // exponential decay coefficient
  var ROW_BASE_DRIFT = 4;        // u/s floor so an idle rowboat crawls rather than fully stalls
  // Nantucket's own threshold is 0.90, not 1.0 — the actual finish still
  // triggers at worldX >= COURSE_LENGTH (frac 1.0), but the backdrop/HUD
  // switch to Nantucket for a final-approach stretch beforehand, so the
  // lighthouse and prize chest are visible before the last frame rather
  // than popping in right as the run ends.
  var CHECKPOINTS = [[0.0,"Charles River"],[0.20,"Boston Harbor"],[0.45,"Cape Cod"],[0.70,"Martha's Vineyard"],[0.90,"Nantucket"]];
  var WHALE_TRIGGER_FRAC = 0.325;  // midpoint of the Boston Harbor segment
  // Whale hazard — every rank including Deckhand (unlike the shark). The
  // danger window (start/end, seconds since trigger) brackets the visible
  // high-opacity/full-size portion of the 3s sdrWhaleBreach animation
  // (opacity hits 1 at the 15% keyframe = 0.45s, starts shrinking back down
  // after the 70% keyframe = 2.1s) so a hit only registers while the whale
  // actually reads as "there." ANIM_DURATION_SEC must track the CSS
  // animation's 3s length so the hazard clears exactly when the whale does.
  var WHALE_DANGER_START_SEC = 0.45, WHALE_DANGER_END_SEC = 2.3;
  var WHALE_HIT_LANE_FRAC = 0.14;
  var WHALE_ANIM_DURATION_SEC = 3;
  // Shark pursuit hazard — Mate+ only (never Deckhand), active from the
  // Martha's Vineyard leg onward (same 0.70 threshold as that checkpoint).
  // Catching the boat is an instant, rank-independent game over, separate
  // from the rock/buoy lives system.
  var SHARK_ACTIVE_FRAC = 0.70;
  var SHARK_LANE_LERP = 1.5;       // per-second lag tracking the boat's lane
  var SHARK_RESET_LERP = 2.0;      // per-second ease back to cruise distance
  var SHARK_CATCH_GAP_UNITS = 12;
  var SHARK_CATCH_LANE_FRAC = 0.09;

  var ROCK_SVG = document.getElementById('sdrRockTpl').innerHTML;
  var BUOY_SVG = document.getElementById('sdrBuoyTpl').innerHTML;

  var root = document.getElementById('sdrRoot');
  var stage = document.getElementById('sdrStage');
  var boatEl = document.getElementById('sdrBoat');
  var boatSailInner = document.getElementById('sdrBoatSailSprite');
  var boatRowInner = document.getElementById('sdrBoatRowSprite');
  var boatInner = boatSailInner;  // sail-only visual state (sdr-sailing) always targets this one
  var oarEl = document.getElementById('sdrOar');  // rowboat-only; see bumpOarStroke
  var obstacleContainer = document.getElementById('sdrObstacles');
  var gustContainer = document.getElementById('sdrGusts');
  var preGame = document.getElementById('sdrPreGame');
  var introEl = document.getElementById('sdrIntro');
  var gameOver = document.getElementById('sdrGameOver');
  var steerZone = document.getElementById('sdrSteerZone');
  var rowBtn = document.getElementById('sdrRowBtn');
  var whaleEl = document.getElementById('sdrWhale');
  var prizeEl = document.getElementById('sdrPrize');
  var sharkEl = document.getElementById('sdrShark');
  var skylineLayers = Array.prototype.slice.call(document.querySelectorAll('.sdr-skyline-layer'));
  var minimapDots = Array.prototype.slice.call(document.querySelectorAll('.sdr-minimap-dot'));

  var touchCapable = ('ontouchstart' in window) || navigator.maxTouchPoints > 0;
  if (touchCapable) root.classList.add('sdr-touch');

  var selectedRank = 'mate';
  var selectedBoat = 'sailboat';
  var state = {
    started: false, over: false, outcome: '',
    rank: 'mate', boat: 'sailboat', worldX: 0, boatY: 0.5, targetY: 0.5,
    hits: 0, invincibleUntil: 0, rowMomentum: 0,
    obstacles: [], gustZones: [], score: 0, startTs: 0, lastTs: 0,
    whaleTriggered: false, whaleActive: false, whaleLane: 0.5, whaleTriggerTs: 0,
    checkpointIdx: 0,
    sharkActive: false, sharkLane: 0.5, sharkGap: 0,
    sharkLunging: false, sharkLungeElapsed: 0, sharkNextLungeAt: 0,
  };

  function isoWeekKey(date){
    var d = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()));
    var dayNum = (d.getUTCDay() + 6) % 7;
    d.setUTCDate(d.getUTCDate() - dayNum + 3);
    var firstThursday = new Date(Date.UTC(d.getUTCFullYear(), 0, 4));
    var firstDayNum = (firstThursday.getUTCDay() + 6) % 7;
    firstThursday.setUTCDate(firstThursday.getUTCDate() - firstDayNum + 3);
    var week = 1 + Math.round((d - firstThursday) / (7*86400000));
    return d.getUTCFullYear() + '-W' + String(week).padStart(2,'0');
  }

  function fnv1a(str){
    var h = 0x811c9dc5;
    for (var i=0;i<str.length;i++){
      h ^= str.charCodeAt(i);
      h = Math.imul(h, 0x01000193);
    }
    return h >>> 0;
  }

  function mulberry32(seed){
    return function(){
      seed |= 0; seed = (seed + 0x6D2B79F5) | 0;
      var t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }

  function currentWeekKey(){ return isoWeekKey(new Date()); }

  function buildObstacles(rankKey){
    var cfg = RANK_SETTINGS[rankKey];
    var seed = fnv1a(currentWeekKey() + '|' + rankKey);
    var rand = mulberry32(seed);
    var count = Math.max(1, Math.round(cfg.obstacle_density * COURSE_LENGTH / 1000));
    obstacleContainer.innerHTML = '';
    var obstacles = [];
    var avgGap = (COURSE_LENGTH - 500) / (count + 1);
    var x = 350;
    for (var i=0;i<count;i++){
      x += avgGap*0.55 + rand()*avgGap*0.9;
      if (x > COURSE_LENGTH - 150) break;
      var type = rand() < 0.5 ? 'rock' : 'buoy';
      var lane = 0.08 + rand()*0.84;
      var el = document.createElement('div');
      el.className = 'sdr-obstacle sdr-' + type;
      el.innerHTML = '<div class="sdr-obstacle-inner">' + (type === 'rock' ? ROCK_SVG : BUOY_SVG) + '</div>';
      obstacleContainer.appendChild(el);
      obstacles.push({worldX:x, lane:lane, type:type, el:el, resolved:false});
    }
    state.obstacles = obstacles;
  }

  // Independent seed/PRNG from obstacles (own '|gust' suffix) so retuning
  // gust coverage never reshuffles rock/buoy placement or vice versa.
  function buildGustZones(rankKey){
    var cfg = RANK_SETTINGS[rankKey];
    var seed = fnv1a(currentWeekKey() + '|' + rankKey + '|gust');
    var rand = mulberry32(seed);
    var zoneCount = 5;
    var courseStart = 200, courseSpan = COURSE_LENGTH - 400;
    var segment = courseSpan / zoneCount;
    var targetTotal = (cfg.gust_coverage_pct / 100) * COURSE_LENGTH;
    var avgZoneLen = Math.max(60, targetTotal / zoneCount);
    gustContainer.innerHTML = '';
    var zones = [];
    for (var i=0;i<zoneCount;i++){
      var zoneLen = Math.min(segment, Math.max(60, avgZoneLen * (0.6 + rand()*0.8)));
      var segStart = courseStart + i*segment;
      var start = segStart + rand()*Math.max(0, segment - zoneLen);
      var end = Math.min(start + zoneLen, COURSE_LENGTH - 100);
      var el = document.createElement('div');
      el.className = 'sdr-gust';
      el.style.width = ((end - start) * PX_PER_UNIT) + 'px';
      gustContainer.appendChild(el);
      zones.push({startX:start, endX:end, el:el});
    }
    state.gustZones = zones;
  }

  // Own seeded PRNG (own '|whale' suffix) so retuning obstacle/gust
  // placement never reshuffles which lane the whale rises in, or vice versa.
  // Same lane range as rocks/buoys (0.08-0.92) so it reads as one course.
  function buildWhale(rankKey){
    var seed = fnv1a(currentWeekKey() + '|' + rankKey + '|whale');
    var rand = mulberry32(seed);
    state.whaleLane = 0.08 + rand()*0.84;
  }

  function isInGustZone(worldX){
    for (var i=0;i<state.gustZones.length;i++){
      var z = state.gustZones[i];
      if (worldX >= z.startX && worldX <= z.endX) return true;
    }
    return false;
  }

  function livesLabel(cfg){
    if (cfg.collision_limit <= 0) return 'Practice mode';
    var remaining = cfg.collision_limit - state.hits;
    return remaining + (remaining === 1 ? ' life left' : ' lives left');
  }

  function checkpointIndexFor(frac){
    var idx = 0;
    for (var i=0;i<CHECKPOINTS.length;i++){ if (frac >= CHECKPOINTS[i][0]) idx = i; }
    return idx;
  }

  function currentCheckpointLabel(){
    return CHECKPOINTS[checkpointIndexFor(state.worldX / COURSE_LENGTH)][1];
  }

  // Crossfades the distant skyline backdrop as the boat crosses into a new
  // checkpoint segment; the water/obstacles/gusts keep scrolling underneath
  // unaffected. Only touches the DOM on an actual index change.
  function updateCheckpointLayer(frac){
    var idx = checkpointIndexFor(frac);
    if (idx === state.checkpointIdx) return;
    state.checkpointIdx = idx;
    var idxStr = String(idx);
    skylineLayers.forEach(function(el){ el.classList.toggle('sdr-active', el.getAttribute('data-cp') === idxStr); });
    minimapDots.forEach(function(el){ el.classList.toggle('sdr-active', parseInt(el.getAttribute('data-cp'), 10) <= idx); });
    document.getElementById('sdrMinimapLabel').textContent = CHECKPOINTS[idx][1];
    prizeEl.style.display = idx === 4 ? 'block' : 'none';
  }

  function maybeTriggerWhale(frac, elapsedSec){
    if (state.whaleTriggered || frac < WHALE_TRIGGER_FRAC) return;
    state.whaleTriggered = true;
    state.whaleActive = true;
    state.whaleTriggerTs = elapsedSec;
    whaleEl.classList.remove('sdr-breach');
    void whaleEl.offsetWidth;
    whaleEl.classList.add('sdr-breach');
  }

  // Every rank including Deckhand (unlike the shark, which skips it) — a
  // hit is instant, rank-independent game over, same as the shark, not
  // routed through registerHit/collision_limit. Only live while
  // state.whaleActive (the danger + visible window); clears itself once the
  // breach animation has fully played out so the whale can't linger as a
  // hazard after it's already faded from view.
  function updateWhale(elapsedSec){
    if (!state.whaleActive) return;
    var t = elapsedSec - state.whaleTriggerTs;
    if (t >= WHALE_DANGER_START_SEC && t <= WHALE_DANGER_END_SEC &&
        Math.abs(state.boatY - state.whaleLane) <= WHALE_HIT_LANE_FRAC){
      endRun('breached');
      return;
    }
    if (t >= WHALE_ANIM_DURATION_SEC) state.whaleActive = false;
  }

  // Shark pursuit: Mate+ only, spawns once the boat crosses into the
  // Martha's Vineyard leg and stays active through the finish. Cruise state
  // holds a following distance and tracks the boat's lane with a lag (room
  // to juke); Lunge state periodically closes that gap hard, then resets.
  // Catching the boat (gap and lane both within tolerance) is an instant,
  // rank-independent game over — separate from the rock/buoy lives system,
  // no extra score penalty beyond whatever DistanceFraction/Pace had reached.
  function updateShark(dt, cfg, frac, elapsedSec){
    if (state.rank === 'deckhand') return;
    if (frac < SHARK_ACTIVE_FRAC){
      state.sharkActive = false;
      return;
    }
    if (!state.sharkActive){
      state.sharkActive = true;
      state.sharkGap = cfg.shark_cruise_distance;
      state.sharkLane = state.boatY;
      state.sharkLunging = false;
      state.sharkNextLungeAt = elapsedSec + cfg.shark_lunge_interval_sec;
    }

    state.sharkLane += (state.boatY - state.sharkLane) * Math.min(1, dt * SHARK_LANE_LERP);

    if (!state.sharkLunging && elapsedSec >= state.sharkNextLungeAt){
      state.sharkLunging = true;
      state.sharkLungeElapsed = 0;
    }
    if (state.sharkLunging){
      state.sharkLungeElapsed += dt;
      state.sharkGap = Math.max(0, state.sharkGap - cfg.shark_lunge_speed * dt);
      if (state.sharkLungeElapsed >= cfg.shark_lunge_duration_sec){
        state.sharkLunging = false;
        state.sharkNextLungeAt = elapsedSec + cfg.shark_lunge_interval_sec;
      }
    } else {
      state.sharkGap += (cfg.shark_cruise_distance - state.sharkGap) * Math.min(1, dt * SHARK_RESET_LERP);
    }

    if (state.sharkGap <= SHARK_CATCH_GAP_UNITS &&
        Math.abs(state.sharkLane - state.boatY) <= SHARK_CATCH_LANE_FRAC){
      endRun('eaten');
    }
  }

  // Score = round(100 * DistanceFraction * PaceMultiplier), capped at 100,
  // minus a CollisionPenalty (0 for Deckhand regardless of hits — true
  // no-penalty practice mode; 10/hit for Mate/First Mate/Skipper), floored
  // at 0. No Efficiency/Stamina term — removed along with rowing.
  function computeScore(cfg, distanceFraction, elapsedSec, hits, rank){
    var paceMult = elapsedSec > 0 ? (cfg.par_time_seconds * distanceFraction) / elapsedSec : 1;
    paceMult = Math.min(1.3, Math.max(0.7, paceMult));
    var raw = Math.min(100, Math.round(100 * distanceFraction * paceMult));
    var collisionPenalty = (rank === 'deckhand') ? 0 : hits * 10;
    return Math.max(0, raw - collisionPenalty);
  }

  function bumpFlash(){
    stage.classList.remove('sdr-flash');
    void stage.offsetWidth;
    stage.classList.add('sdr-flash');
  }

  function bumpOarStroke(){
    oarEl.classList.remove('sdr-stroke');
    // oarEl is an SVG <g> — .offsetWidth (the usual reflow-forcing read,
    // see bumpFlash above) is undefined on SVG elements and doesn't force
    // a style recalculation, so the animation only ever restarted on the
    // very first stroke. getBoundingClientRect() is defined on all
    // Element types and reliably forces the recalc needed to restart a
    // CSS animation via remove+reflow+re-add.
    void oarEl.getBoundingClientRect();
    oarEl.classList.add('sdr-stroke');
  }

  function registerHit(cfg, now){
    bumpFlash();
    if (cfg.collision_limit <= 0) return;
    if (now < state.invincibleUntil) return;
    state.hits += 1;
    if (cfg.grace_window) state.invincibleUntil = now + GRACE_MS;
    if (state.hits >= cfg.collision_limit) endRun('sunk');
  }

  function tryCollision(ob, cfg, now){
    if (ob.resolved) return;
    var dx = ob.worldX - state.worldX;
    // "resolved" means "boat has moved past this obstacle" (cleanup, stop
    // checking it) — it must NOT also mean "already hit once." A hit is
    // debounced by registerHit's own invincibleUntil window, not by
    // permanently disabling the obstacle; otherwise a boat that lingers in
    // an obstacle's hitbox (e.g. a rowboat stalled with near-zero momentum)
    // past the grace window never takes a second hit, even though it's
    // still in continuous contact.
    if (dx < -HITBOX_X_UNITS){ ob.resolved = true; return; }
    if (dx > HITBOX_X_UNITS) return;
    if (Math.abs(ob.lane - state.boatY) > HITBOX_LANE_FRAC) return;
    registerHit(cfg, now);
  }

  function hiKeyFor(rank){ return 'sdr_hi_' + rank; }
  function storedHi(rank){ return parseInt(localStorage.getItem(hiKeyFor(rank)) || '0', 10); }

  function formatTime(sec){
    sec = Math.max(0, Math.round(sec));
    var m = Math.floor(sec / 60), s = sec % 60;
    return m + ':' + (s < 10 ? '0' : '') + s;
  }

  function endRun(reason){
    if (state.over) return;  // guards against a same-frame finish+shark-catch race
    state.over = true;
    state.outcome = reason;  // 'finish' | 'sunk' | 'eaten' | 'breached'
    var prevHi = storedHi(state.rank);
    if (state.score > prevHi) localStorage.setItem(hiKeyFor(state.rank), String(state.score));

    var distanceFraction = state.worldX / COURSE_LENGTH;
    var elapsedSec = (performance.now() - state.startTs) / 1000;

    var title = reason === 'finish' ? "You made it to Nantucket 🏆" :
                reason === 'eaten' ? "Caught!" :
                reason === 'breached' ? "Capsized!" : 'Sunk';
    document.getElementById('sdrOutcomeTitle').textContent = title;
    document.getElementById('sdrOutcomeSub').textContent =
      Math.round(distanceFraction * 100) + '% of the course \\u00b7 Score ' + state.score;

    document.getElementById('sdrStatScore').textContent = state.score;
    document.getElementById('sdrStatDistance').textContent = Math.round(distanceFraction * 100) + '%';
    document.getElementById('sdrStatTime').textContent = formatTime(elapsedSec);
    document.getElementById('sdrStatHits').textContent = state.hits;

    var furthestRow = document.getElementById('sdrOutcomeFurthest');
    if (reason === 'finish') {
      furthestRow.style.display = 'none';
    } else {
      furthestRow.style.display = 'block';
      document.getElementById('sdrStatFurthest').textContent = currentCheckpointLabel();
    }

    gameOver.classList.toggle('sdr-finish', reason === 'finish');
    gameOver.style.display = 'flex';
    requestAnimationFrame(function(){ gameOver.classList.add('sdr-visible'); });

    if (SIGNED_IN) submitScore(state.rank, state.score, distanceFraction, reason === 'finish', elapsedSec, state.hits);
  }

  function submitScore(rank, score, distanceFraction, finished, timeSeconds, hits){
    var statusEl = document.getElementById('sdrSubmitStatus');
    fetch('/play/submit', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({
        rank: rank, score: score, distance_fraction: distanceFraction,
        finished: finished, time_seconds: timeSeconds, hits: hits,
      }),
    }).then(function(r){ return r.json(); }).then(function(data){
      if (statusEl) statusEl.textContent = data.ok ? 'Saved to the leaderboard.' : 'Could not save this run.';
    }).catch(function(){
      if (statusEl) statusEl.textContent = 'Could not save this run.';
    });
  }

  function startRun(rankKey, boatKey){
    state.rank = rankKey;
    state.boat = boatKey || state.boat;
    state.worldX = 0; state.boatY = 0.5; state.targetY = 0.5;
    state.hits = 0; state.invincibleUntil = 0; state.rowMomentum = 0;
    state.over = false; state.outcome = ''; state.score = 0;
    state.whaleTriggered = false; state.whaleActive = false; state.whaleTriggerTs = 0;
    state.checkpointIdx = 0;
    state.sharkActive = false; state.sharkLunging = false;
    state.startTs = performance.now(); state.lastTs = 0;
    buildObstacles(rankKey);
    buildGustZones(rankKey);
    buildWhale(rankKey);
    whaleEl.classList.remove('sdr-breach');
    whaleEl.style.display = 'none';
    sharkEl.classList.remove('sdr-lunging');
    sharkEl.style.display = 'none';
    skylineLayers.forEach(function(el){ el.classList.toggle('sdr-active', el.getAttribute('data-cp') === '0'); });
    minimapDots.forEach(function(el){ el.classList.toggle('sdr-active', el.getAttribute('data-cp') === '0'); });
    document.getElementById('sdrMinimapLabel').textContent = CHECKPOINTS[0][1];
    prizeEl.style.display = 'none';
    preGame.style.display = 'none';
    introEl.style.display = 'none';
    gameOver.classList.remove('sdr-visible', 'sdr-finish');
    gameOver.style.display = 'none';
    stage.style.display = 'block';
    state.started = true;
    // Swap in the selected boat's sprite — see _SDR_ROWBOAT_SVG for why this
    // is two pre-rendered sprites toggled by display, not one dynamically
    // rebuilt element.
    boatSailInner.style.display = (state.boat === 'rowboat') ? 'none' : 'block';
    boatRowInner.style.display = (state.boat === 'rowboat') ? 'block' : 'none';
    // Mobile row button — only for the rowboat, and only on touch devices;
    // sailboat play and desktop play must never show it.
    rowBtn.style.display = (touchCapable && state.boat === 'rowboat') ? 'flex' : 'none';
    showPortraitToastIfNeeded();
  }

  function backToRankSelect(){
    state.started = false;
    gameOver.classList.remove('sdr-visible');
    gameOver.style.display = 'none';
    stage.style.display = 'none';
    preGame.style.display = 'block';
    introEl.style.display = '';
    rowBtn.style.display = 'none';
  }

  // -- Pre-game rank selector --
  var pills = root.querySelectorAll('.sdr-rank-pill');
  pills.forEach(function(pill){
    pill.addEventListener('click', function(){
      pills.forEach(function(p){ p.classList.remove('sdr-active'); });
      pill.classList.add('sdr-active');
      selectedRank = pill.getAttribute('data-rank');
      document.getElementById('sdrPreHi').textContent = storedHi(selectedRank);
    });
  });
  document.getElementById('sdrPreHi').textContent = storedHi(selectedRank);

  // -- Pre-game boat selector — independent axis from rank; see _SDR_BOATS. --
  var boatPills = root.querySelectorAll('.sdr-boat-pill');
  boatPills.forEach(function(pill){
    pill.addEventListener('click', function(){
      boatPills.forEach(function(p){ p.classList.remove('sdr-active'); });
      pill.classList.add('sdr-active');
      selectedBoat = pill.getAttribute('data-boat');
    });
  });

  document.getElementById('sdrStartBtn').addEventListener('click', function(){ startRun(selectedRank, selectedBoat); });
  document.getElementById('sdrRetryBtn').addEventListener('click', function(){ startRun(state.rank, state.boat); });
  document.getElementById('sdrChangeRankBtn').addEventListener('click', backToRankSelect);

  // -- Rowing: each call adds one burst and retriggers the single-oar sweep
  // (bumpOarStroke); decay happens continuously in update(). Only has any
  // effect for the rowboat — a no-op for the sailboat, which has no manual
  // propulsion input by design.
  function row(){
    if (!state.started || state.over || state.boat !== 'rowboat') return;
    state.rowMomentum = Math.min(ROW_MAX_MOMENTUM, state.rowMomentum + ROW_BURST_ADD);
    bumpOarStroke();
  }

  // -- Keyboard (steering + spacebar-to-row on the rowboat) --
  // Rowing fires on release, not press: holding Space down must not
  // propel the boat on its own — each stroke is a deliberate press-and-
  // release, which is harder to fit around steering than a hold-to-win
  // button would be (see the ROW_* constants' comment above).
  var keyUp = false, keyDown = false, spaceDown = false;
  window.addEventListener('keydown', function(e){
    if (!state.started || state.over) return;
    if (e.code === 'ArrowUp'){ keyUp = true; e.preventDefault(); }
    if (e.code === 'ArrowDown'){ keyDown = true; e.preventDefault(); }
    if (e.code === 'Space'){ spaceDown = true; e.preventDefault(); }
  });
  window.addEventListener('keyup', function(e){
    if (e.code === 'ArrowUp') keyUp = false;
    if (e.code === 'ArrowDown') keyDown = false;
    if (e.code === 'Space' && spaceDown){ spaceDown = false; row(); }
  });

  // -- Mobile row button (rowboat + touch only; see startRun/backToRankSelect
  // for the display toggle). Same press-and-release rule as Space: the
  // stroke fires on pointerup, not pointerdown. setPointerCapture keeps
  // pointerup targeting this element even if the finger drifts slightly. --
  var rowPressed = false;
  rowBtn.addEventListener('pointerdown', function(e){
    e.preventDefault();
    rowPressed = true;
    try { rowBtn.setPointerCapture(e.pointerId); } catch(err){}
  });
  rowBtn.addEventListener('pointerup', function(){ if (rowPressed){ rowPressed = false; row(); } });
  rowBtn.addEventListener('pointercancel', function(){ rowPressed = false; });

  // -- Touch/pointer steer-drag --
  var dragging = false;
  function setTargetFromClientY(clientY){
    var rect = stage.getBoundingClientRect();
    var frac = (clientY - rect.top - rect.height*CHANNEL_TOP) / (rect.height*(CHANNEL_BOTTOM-CHANNEL_TOP));
    state.targetY = Math.min(1, Math.max(0, frac));
  }
  steerZone.addEventListener('pointerdown', function(e){
    dragging = true; setTargetFromClientY(e.clientY);
    try { steerZone.setPointerCapture(e.pointerId); } catch(err){}
  });
  steerZone.addEventListener('pointermove', function(e){ if (dragging) setTargetFromClientY(e.clientY); });
  steerZone.addEventListener('pointerup', function(){ dragging = false; });
  steerZone.addEventListener('pointercancel', function(){ dragging = false; });

  // -- Portrait footnote: an auto-dismissing toast shown once per run start,
  // not a persistent element (it used to sit on top of active gameplay).
  var portraitToastTimer = null;
  function showPortraitToastIfNeeded(){
    var note = document.getElementById('sdrPortraitNote');
    if (touchCapable && window.matchMedia('(orientation: portrait)').matches){
      note.classList.remove('sdr-toast-out');
      note.style.display = 'block';
      clearTimeout(portraitToastTimer);
      portraitToastTimer = setTimeout(function(){ note.classList.add('sdr-toast-out'); }, 2500);
    } else {
      note.style.display = 'none';
    }
  }

  // -- Update / render --
  function update(dt, ts){
    if (keyUp) state.targetY = Math.max(0, state.targetY - STEER_KEY_RATE*dt);
    if (keyDown) state.targetY = Math.min(1, state.targetY + STEER_KEY_RATE*dt);
    state.boatY += (state.targetY - state.boatY) * Math.min(1, dt*BOAT_LERP);

    var cfg = RANK_SETTINGS[state.rank];
    var elapsedSec = (ts - state.startTs) / 1000;
    var speed;
    if (state.boat === 'rowboat'){
      // Manual propulsion only — no speed ramp, no gust boost (locked
      // decision: the gust mechanic stays sailboat-only). Momentum decays
      // continuously; row() adds bursts on each press/tap.
      state.rowMomentum -= state.rowMomentum * ROW_DECAY_PER_SEC * dt;
      if (state.rowMomentum < 0.01) state.rowMomentum = 0;
      speed = ROW_BASE_DRIFT + state.rowMomentum;
      boatInner.classList.remove('sdr-sailing');
    } else {
      // No manual rowing — forward speed is a base that ramps up over
      // elapsed run time (the difficulty lever, replacing the old row
      // mechanic), plus an automatic, purely positional boost while inside
      // a gust zone.
      var sailing = isInGustZone(state.worldX);
      var baseSpeed = cfg.drift_speed + cfg.speed_ramp_per_sec * elapsedSec;
      speed = baseSpeed + (sailing ? cfg.sail_speed : 0);
      boatInner.classList.toggle('sdr-sailing', sailing);
    }
    state.worldX = Math.min(COURSE_LENGTH, state.worldX + speed*dt);

    var distanceFraction = state.worldX / COURSE_LENGTH;
    state.score = computeScore(cfg, distanceFraction, elapsedSec, state.hits, state.rank);

    updateCheckpointLayer(distanceFraction);
    maybeTriggerWhale(distanceFraction, elapsedSec);
    updateWhale(elapsedSec);
    if (state.over) return;  // updateWhale may have ended the run (breached)
    updateShark(dt, cfg, distanceFraction, elapsedSec);
    if (state.over) return;  // updateShark may have ended the run (caught)

    if (state.worldX >= COURSE_LENGTH){ endRun('finish'); return; }

    for (var i=0;i<state.obstacles.length;i++) tryCollision(state.obstacles[i], cfg, ts);
  }

  function render(){
    if (!state.started) return;
    var rect = stage.getBoundingClientRect();
    var boatX = rect.width * BOAT_X_FRAC;
    var boatY = rect.height * (CHANNEL_TOP + state.boatY*(CHANNEL_BOTTOM-CHANNEL_TOP));
    var bw = boatEl.offsetWidth, bh = boatEl.offsetHeight;
    boatEl.style.transform = 'translate(' + (boatX-bw*0.5) + 'px,' + (boatY-bh*0.78) + 'px)';

    for (var i=0;i<state.obstacles.length;i++){
      var ob = state.obstacles[i];
      var sx = boatX + (ob.worldX - state.worldX) * PX_PER_UNIT;
      if (sx < -60 || sx > rect.width + 60){ ob.el.style.display = 'none'; continue; }
      ob.el.style.display = 'block';
      var sy = rect.height * (CHANNEL_TOP + ob.lane*(CHANNEL_BOTTOM-CHANNEL_TOP));
      var ow = ob.el.offsetWidth, oh = ob.el.offsetHeight;
      ob.el.style.transform = 'translate(' + (sx-ow*0.5) + 'px,' + (sy-oh*0.5) + 'px)';
    }

    for (var g=0;g<state.gustZones.length;g++){
      var z = state.gustZones[g];
      var gsx = boatX + (z.startX - state.worldX) * PX_PER_UNIT;
      var gw = z.el.offsetWidth;
      if (gsx + gw < -50 || gsx > rect.width + 50){ z.el.style.display = 'none'; continue; }
      z.el.style.display = 'block';
      z.el.style.transform = 'translateX(' + gsx + 'px)';
    }

    if (state.whaleActive){
      whaleEl.style.display = 'block';
      var wlX = rect.width * WHALE_X_FRAC;
      var wlY = rect.height * (CHANNEL_TOP + state.whaleLane*(CHANNEL_BOTTOM-CHANNEL_TOP));
      var wlW = whaleEl.offsetWidth, wlH = whaleEl.offsetHeight;
      whaleEl.style.transform = 'translate(' + (wlX-wlW*0.5) + 'px,' + (wlY-wlH*0.5) + 'px)';
    } else {
      whaleEl.style.display = 'none';
    }

    if (state.sharkActive){
      sharkEl.style.display = 'block';
      sharkEl.classList.toggle('sdr-lunging', state.sharkLunging);
      var shX = boatX - state.sharkGap * PX_PER_UNIT;
      var shY = rect.height * (CHANNEL_TOP + state.sharkLane*(CHANNEL_BOTTOM-CHANNEL_TOP));
      var shW = sharkEl.offsetWidth, shH = sharkEl.offsetHeight;
      sharkEl.style.transform = 'translate(' + (shX-shW*0.5) + 'px,' + (shY-shH*0.5) + 'px)';
    } else {
      sharkEl.style.display = 'none';
    }

    var cfg = RANK_SETTINGS[state.rank];
    document.getElementById('sdrMinimapFill').style.width = (Math.min(1, state.worldX / COURSE_LENGTH) * 100) + '%';
    document.getElementById('sdrScore').textContent = state.score;
    document.getElementById('sdrHi').textContent = Math.max(state.score, storedHi(state.rank));
    document.getElementById('sdrLives').textContent = livesLabel(cfg);
  }

  function loop(ts){
    if (!state.lastTs) state.lastTs = ts;
    var dt = Math.min((ts - state.lastTs) / 1000, 0.05);
    state.lastTs = ts;
    if (state.started && !state.over) update(dt, ts);
    render();
    requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);
})();
"""

_SDR_COURSE_LENGTH = 4300
_SDR_RANKS = {"deckhand", "mate", "first_mate", "skipper"}


def _sdr_course_week(dt=None) -> str:
    """ISO week string ('2026-W27') tagging a run to a course-week, computed
    server-side (never trust a client-supplied value). The client's own
    isoWeekKey() derives the same string from the *player's local* calendar
    date rather than true UTC, so a player right at a week boundary in an
    extreme timezone could rarely see a course generated for a different
    week than the one their run gets tagged with here — a cosmetic label
    mismatch, not a gameplay bug, and not worth the complexity of threading
    timezone through the client/server boundary for a personal leaderboard."""
    dt = dt or datetime.now(timezone.utc)
    iso_year, iso_week, _ = dt.isocalendar()
    return f"{iso_year}-W{iso_week:02d}"


def _sdr_difficulty_index(gust_coverage_pct: float, obstacle_density: float) -> int:
    """0-100. Mirrors the Phase 0 formula and the client's own obstacle-count/
    avg-gap derivation (buildObstacles' avgGap is a deterministic function of
    obstacle_density and course length, not of the random seed — so this is
    computable server-side without re-running the client's PRNG)."""
    count = max(1, round(obstacle_density * _SDR_COURSE_LENGTH / 1000))
    avg_gap = (_SDR_COURSE_LENGTH - 500) / (count + 1)
    gap_norm = min(1.0, avg_gap / 400.0)
    gust_frac = gust_coverage_pct / 100.0
    density_norm = min(1.0, obstacle_density / 9.0)  # 9 = Skipper's default, the reference "max"
    raw = 0.4 * (1 - gust_frac) + 0.4 * density_norm + 0.2 * (1 - gap_norm)
    return round(100 * max(0.0, min(1.0, raw)))


def _sdr_difficulty_label(index: int) -> str:
    if index <= 30:
        return "Fair Winds"
    if index <= 55:
        return "Choppy Waters"
    if index <= 80:
        return "Rough Seas"
    return "Storm Warning"


