@app.get("/tools/benchmarks", response_class=HTMLResponse)
def tools_benchmarks(request: Request):
    authed = _is_authed(request)
    lib = _lib()
    try:
        benchmarks = lib.list_benchmarks()
    finally:
        lib.close()

    def _bench_badge_style(cov: str) -> str:
        return {
            "Private": "background:#dbeafe;color:#1d4ed8",
            "Public":  "background:#dcfce7;color:#16a34a",
            "Both":    "background:#ede9fe;color:#7c3aed",
        }.get(cov, "background:var(--accent-light);color:var(--accent)")

    def _bench_pricing_badge(b: dict) -> str:
        p = (b.get("pricing") or "free").lower()
        if p == "paid":
            label = "$ Paid"
        elif p == "freemium":
            label = "$ Free + paid"
        else:
            return ""
        return (f'<span class="bench-badge" title="Paid resource" '
                f'style="background:#fef3c7;color:#92400e;">{label}</span>')

    bench_cards = "".join(
        f'<a class="bench-card" href="{_esc(b["url"])}" target="_blank" rel="noopener">'
        f'<div style="display:flex;align-items:baseline;justify-content:space-between;gap:8px;margin-bottom:8px;">'
        f'<span class="bench-name">{_esc(b["name"])}</span>'
        f'<span style="display:flex;gap:6px;align-items:center;flex-shrink:0;">'
        f'{_bench_pricing_badge(b)}'
        f'<span class="bench-badge" style="{_bench_badge_style(b["coverage"])}">{_esc(b["coverage"])}</span>'
        f'</span>'
        f'</div>'
        f'<p class="bench-desc">{_esc(b["description"])}</p>'
        f'</a>'
        for b in benchmarks
    )

    body = f"""<div class="page page-grid">
<p style="margin:0 0 4px;"><a href="/tools" style="font-size:13px;color:var(--muted);">&larr; Toolbox</a></p>
<div style="display:flex;align-items:baseline;justify-content:space-between;flex-wrap:wrap;gap:12px;">
  <h1 style="margin:0;">Benchmarking</h1>
  {'<a href="/admin/tools/benchmarks" style="font-size:14px;font-weight:500;">Manage →</a>' if authed else ''}
</div>
<p style="color:var(--muted);font-size:14px;margin:8px 0 12px;">The benchmarking sources I actually use.</p>
<p style="font-size:13px;color:var(--muted);margin:0 0 24px;">Worth reading first: <a href="https://www.onlycfo.io/p/benchmarking-is-bad" target="_blank" rel="noopener" style="color:var(--accent);font-weight:500;">Benchmarking is Bad</a>&mdash;it&rsquo;s not always what you think it is.</p>
<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:14px;">
  {bench_cards}
</div>
</div>

<style>
.bench-card{{display:block;background:#fff;border:1px solid var(--line);border-radius:14px;padding:18px 20px;text-decoration:none;transition:border-color .15s;}}
.bench-card:hover{{border-color:var(--accent);text-decoration:none;}}
.bench-name{{font-size:15px;font-weight:600;color:var(--ink);}}
.bench-card:hover .bench-name{{color:var(--accent);}}
.bench-badge{{font-size:11px;font-weight:500;border-radius:6px;padding:2px 8px;white-space:nowrap;flex-shrink:0;}}
.bench-desc{{font-size:13px;color:var(--ink-soft);margin:0;line-height:1.5;}}
</style>"""
    return HTMLResponse(_page("Benchmarking—Brian Weisberg", "CFO Toolbox", body, role=_role(request)))


def _visitor_session_id(request: Request) -> str:
    """Existing cfo_visitor cookie value, or a freshly generated one if the
    visitor doesn't have one yet. Caller is responsible for actually setting
    the cookie on the response via _set_visitor_cookie — reading here never
    has a side effect."""
    return request.cookies.get(VISITOR_COOKIE_NAME) or secrets.token_urlsafe(16)


def _set_visitor_cookie(request: Request, resp, session_id: str) -> None:
    """Sets cfo_visitor only when the visitor doesn't already have one —
    avoids resetting the 30-day TTL (and sending a Set-Cookie header) on
    every single page view."""
    if request.cookies.get(VISITOR_COOKIE_NAME):
        return
    secure = (request.url.scheme == "https" or request.headers.get("x-forwarded-proto") == "https")
    resp.set_cookie(VISITOR_COOKIE_NAME, session_id, max_age=VISITOR_SESSION_TTL,
                    httponly=True, samesite="lax", secure=secure, path="/")


@app.get("/tools/communities", response_class=HTMLResponse)
def tools_communities(request: Request):
    is_member = _is_member(request)  # submit is account-only
    lib = _lib()
    try:
        communities = [_public_community(c) for c in lib.list_communities(approved_only=True)]
        categories = lib.list_community_categories()
    finally:
        lib.close()

    import json as _json

    def _community_entry(c: dict) -> dict:
        return {
            "id": c["id"],
            "name": c["name"],
            "url": c["url"],
            "slug": c["slug"],
            "reach": c.get("reach") or "National",
            "local_markets": c.get("local_markets") or "",
            "demographic": c["demographic"],
            "cost_band": c["cost_band"],
            "cost_note": c.get("cost_note") or "",
            "sponsorship_type": c.get("sponsorship_type") or "",
            "sponsor_name": c.get("sponsor_name") or "",
            "access": c.get("access") or "",
            "format": c.get("format") or "",
            "notes": c.get("notes") or "",
            "logo_url": _community_logo_url(c),
            "categories": c["categories"],
            "featured": bool(c.get("featured")),
            "advisor": bool(c.get("advisor")),
        }

    communities_json = _json.dumps([_community_entry(c) for c in communities])
    cat_buttons = "".join(
        f'<button class="ccat-btn" data-cat="{_esc(c["name"])}" onclick="filterCommCat(this)"'
        f' title="{_esc(c["description"])}">{_esc(c["name"])}</button>'
        for c in categories
    )
    # "Uncategorized" is a hygiene filter (Phase J3), not a real category — a
    # reserved data-cat sentinel the JS OR-matches against an empty
    # categories array instead of a category name (see commFiltered() below).
    cat_buttons += '<button class="ccat-btn" data-cat="__uncategorized__" onclick="filterCommCat(this)">Uncategorized</button>'
    cost_bands = ["Free", "Undisclosed dues", "<$1k/yr", "<$2,500/yr", "$2,500+/yr"]
    cost_buttons = "".join(
        f'<button class="ccat-btn" data-cost="{_esc(b)}" onclick="filterCommCost(this)">{_esc(b)}</button>'
        for b in cost_bands
    )

    body = f"""<div class="page page-grid">
<p style="margin:0 0 4px;"><a href="/tools" style="font-size:13px;color:var(--muted);">&larr; Toolbox</a></p>
<h1 style="margin:0;">Communities</h1>
<p style="color:var(--muted);margin:8px 0 28px;">A directory of CFO and finance communities worth joining: peer
groups, associations, and Slack channels. Not sure which community's for you? {(
    '<a href="/tools/communities/find" style="font-weight:500;">Community Matchmaker &rarr;</a>'
    if is_member else
    '<a href="/login?next=%2Ftools%2Fcommunities%2Ffind" style="font-weight:500;">Sign in for access to Community Matchmaker &rarr;</a>'
)}</p>

<div style="display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-bottom:12px;">
  <input id="comm-search" type="search" placeholder="Search communities…"
    oninput="filterCommunities()"
    style="flex:1;min-width:200px;max-width:400px;padding:10px 14px;border:1px solid var(--line);border-radius:10px;font:inherit;font-size:15px;background:#fff;">
  <button id="comm-advisor-btn" class="ccat-btn" onclick="toggleCommAdvisor()" style="border-color:var(--accent);color:var(--accent);">&#9733; Advisor</button>
  <select id="comm-access" onchange="filterCommunities()"
    style="padding:10px 14px;border:1px solid var(--line);border-radius:10px;font:inherit;font-size:14px;background:#fff;color:var(--ink);">
    <option value="">All access types</option>
    <option value="Invite-only">Invite-only</option>
    <option value="Application">Application</option>
    <option value="Open">Open</option>
    <option value="Other">Other</option>
  </select>
</div>

<details open style="margin-bottom:8px;">
  <summary style="cursor:pointer;font-size:13px;color:var(--muted);display:inline-flex;align-items:center;gap:5px;margin-bottom:8px;">Categories <span class="disclosure-caret" style="font-size:12px;">&#9654;</span></summary>
  <div style="display:flex;gap:10px;flex-wrap:wrap;align-items:center;">
    <button class="ccat-btn ccat-all ccat-active" data-cat="" onclick="filterCommCat(this)">All categories</button>
    {cat_buttons}
  </div>
</details>

<div style="display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-bottom:16px;">
  <button class="ccat-btn ccat-all ccat-active" data-cost="" onclick="filterCommCost(this)">All cost bands</button>
  {cost_buttons}
</div>

<div id="comm-count" style="font-size:13px;color:var(--muted);margin-bottom:16px;"></div>

<div id="comm-grid" style="display:grid;grid-template-columns:repeat(auto-fill,minmax(320px,1fr));gap:14px;align-items:start;">
</div>

<div id="comm-pagination" style="display:none;align-items:center;justify-content:center;gap:14px;margin:24px 0 8px;"></div>

<div id="comm-compare-bar" style="display:none;position:sticky;bottom:16px;margin-top:20px;background:var(--navy);
  border-radius:12px;padding:14px 20px;align-items:center;gap:14px;flex-wrap:wrap;box-shadow:0 4px 16px rgba(0,0,0,.18);">
  <span id="comm-compare-count" style="color:#fff;font-size:14px;font-weight:600;"></span>
  <span id="comm-compare-msg" style="color:var(--seafoam);font-size:13px;"></span>
  <span style="flex:1;"></span>
  <button type="button" onclick="clearCompareSelection()" class="btn btn-ghost"
    style="font-size:13px;padding:6px 14px;background:transparent;color:#fff;border-color:rgba(255,255,255,.4);">Clear</button>
  <a id="comm-compare-link" href="/tools/communities/compare" class="btn"
    style="font-size:13px;padding:6px 16px;background:var(--seafoam);color:var(--navy);border-color:var(--seafoam);">Compare &rarr;</a>
</div>

<p id="comm-empty" style="display:none;color:var(--muted);padding:32px 0;">No communities match your search.</p>

<div style="margin-top:28px;padding-top:20px;border-top:1px solid var(--line);">
  <p style="font-size:13px;color:var(--muted);margin-bottom:16px;">&#9733; Formal advisor to these communities.</p>
  <p style="font-size:15px;color:var(--muted);">Know a community that belongs here?
    {'<a href="/tools/communities/submit" style="font-weight:500;">Submit it for review →</a>' if is_member else '<a href="/login" style="font-weight:500;">Sign in to submit →</a>'}</p>
  <p style="margin:8px 0 0;font-size:15px;color:var(--muted);">Can't find the right one, or the one you're in isn't quite enough? <a id="comm-gap-link" href="/tools/communities/gap" style="font-weight:500;">I'd love to know what's missing &rarr;</a></p>
</div>
</div>

<style>
.ccat-btn{{font-size:13px;font-weight:500;padding:6px 14px;border-radius:20px;border:1px solid var(--line);
  background:none;color:var(--muted);cursor:pointer;white-space:nowrap;}}
.ccat-btn:hover{{background:var(--accent-light);color:var(--ink);}}
.ccat-active{{background:var(--accent)!important;color:#fff!important;border-color:var(--accent)!important;}}
#comm-pagination .btn:disabled{{opacity:.4;cursor:not-allowed;}}
#comm-pagination .btn:disabled:hover{{background:transparent;color:var(--navy);}}
#comm-pagination-label{{font-size:13px;color:var(--muted);}}
.comm-card{{background:#fff;border:1px solid var(--line);border-radius:14px;padding:18px 20px;display:flex;flex-direction:column;}}
.comm-card-featured{{border-color:var(--coral-light);box-shadow:0 0 0 1px var(--coral-light);}}
.comm-star{{font-size:14px;color:#b8860b;margin-right:4px;flex-shrink:0;}}
/* Same fixed-height technique as .tool-name/.tool-desc on the Software directory
   (webapp/app.py:4916-4931): every variable-length field is clamped to a fixed
   number of lines with a matching min-height, so every card in the grid ends up
   the same height regardless of content length — name, meta line, and the
   demographic+notes description (folded into one clamped paragraph rather than
   an optional extra row, which used to add its own height variance). */
.comm-name{{font-family:var(--font-head);font-size:17px;font-weight:600;color:var(--ink);text-decoration:none;
  display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;overflow:hidden;
  line-height:1.3;min-height:44px;margin-bottom:6px;letter-spacing:-0.01em;}}
.comm-name:hover{{color:var(--navy);}}
.comm-meta{{font-size:13px;color:var(--muted);margin:0 0 8px;line-height:1.5;min-height:39px;
  display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;overflow:hidden;}}
.comm-demo{{font-size:14px;color:var(--ink-soft);margin:0 0 12px;line-height:1.5;min-height:63px;
  display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:3;overflow:hidden;}}
.comm-cats{{display:flex;flex-wrap:wrap;gap:6px;min-height:24px;}}
.comm-cat{{font-size:11px;font-weight:600;color:var(--navy);background:var(--seafoam);border-radius:6px;padding:3px 9px;}}
.comm-cost{{font-size:11px;font-weight:600;color:var(--navy);background:var(--navy-wash);border-radius:6px;padding:3px 9px;white-space:nowrap;}}
.comm-verify{{font-size:11px;font-weight:600;font-style:italic;color:var(--muted);background:none;border:1px dashed var(--line);border-radius:6px;padding:2px 8px;white-space:nowrap;}}
.comm-full-link{{font-size:12px;font-weight:600;color:var(--navy);white-space:nowrap;flex-shrink:0;}}
.comm-compare-label{{font-size:12px;color:var(--muted);display:flex;align-items:center;gap:5px;cursor:pointer;white-space:nowrap;}}
.comm-compare-label input{{cursor:pointer;}}
</style>

<script>
var ALL_COMMUNITIES = {communities_json};
var NEEDS_VERIFICATION = {_json.dumps(_NEEDS_VERIFICATION)};
var activeCommCats = new Set();
var activeCommCost = '';
var commAdvisorOnly = false;
var COMM_PAGE_SIZE = 10;
var commCurrentPage = 0;
var COMPARE_MAX = 3;
var compareSelected = [];

function commEsc(s) {{
  return String(s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}}

// Card-size logo (Phase F3) — same "Logo not available" fallback as
// logoBox() on the Software directory and _logo_box() on the
// server-rendered profile pages. Community cards are always small (28px),
// so this is always the compact icon+tooltip form.
var COMM_LOGO_MISSING_LABEL = 'Logo not available';
var COMM_LOGO_MISSING_ICON_SVG = '<svg width="{{w}}" height="{{w}}" viewBox="0 0 24 24" fill="none" stroke="var(--muted)" '
  + 'stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'
  + '<rect x="3" y="3" width="18" height="18" rx="3"></rect>'
  + '<circle cx="8.5" cy="8.5" r="1.4"></circle>'
  + '<polyline points="21 15 16 10 5 21"></polyline>'
  + '<line x1="2" y1="2" x2="22" y2="22"></line>'
  + '</svg>';

function commLogoBox(name, logoUrl, size) {{
  if (logoUrl) {{
    return '<img src="' + commEsc(logoUrl) + '" alt="' + commEsc(name) + ' logo" loading="lazy" style="width:' + size + 'px;height:' + size + 'px;'
      + 'border-radius:8px;object-fit:contain;background:#fff;border:1px solid var(--line);flex-shrink:0;">';
  }}
  var icon = COMM_LOGO_MISSING_ICON_SVG.split('{{w}}').join(Math.max(12, Math.round(size * 0.55)));
  return '<div role="img" aria-label="' + commEsc(COMM_LOGO_MISSING_LABEL) + '" title="' + commEsc(COMM_LOGO_MISSING_LABEL) + '" '
    + 'style="width:' + size + 'px;height:' + size + 'px;border-radius:8px;flex-shrink:0;'
    + 'background:var(--surface-2);border:1px solid var(--line);display:flex;align-items:center;'
    + 'justify-content:center;">' + icon + '</div>';
}}

// Renders a Community listing field for the directory card: the escaped
// value normally, or a muted "Needs verification" flag (not the vivid
// comm-cost/comm-cat styling of a confirmed value) when it still carries
// the auto-fill sentinel — same treatment as _verify_html on the server-
// rendered compare/profile pages.
function commVerify(s) {{
  if (s === NEEDS_VERIFICATION) return '<span class="comm-verify">Needs verification</span>';
  return commEsc(s);
}}

function accessBucket(access) {{
  var a = (access || '');
  if (a.indexOf('Invite') === 0) return 'Invite-only';
  if (a.indexOf('Application') !== -1 || a.indexOf('Qualification') !== -1) return 'Application';
  if (a.indexOf('Open') === 0) return 'Open';
  return 'Other';
}}

// Regional: just the local markets text (usually one place). National/Global
// with local markets: "<reach> · <local markets>". National/Global with none:
// "Global" or "National · online".
function commGeoLine(c) {{
  if (c.reach === NEEDS_VERIFICATION) return '<span class="comm-verify">Needs verification</span>';
  var localMarkets = c.local_markets || '';
  var reach = c.reach || 'National';
  if (reach === 'Regional') {{
    return commEsc(localMarkets || 'Regional');
  }}
  if (!localMarkets) {{
    return commEsc(reach === 'Global' ? 'Global' : 'National · online');
  }}
  return commEsc(reach + ' · ' + localMarkets);
}}

function gapFormHref(isZero) {{
  var q = document.getElementById('comm-search').value || '';
  var accessType = document.getElementById('comm-access').value || '';
  var params = new URLSearchParams();
  if (q) params.set('q', q);
  if (accessType) params.set('access', accessType);
  if (activeCommCost) params.set('cost', activeCommCost);
  if (activeCommCats.size) params.set('cats', Array.from(activeCommCats).join(','));
  if (commAdvisorOnly) params.set('advisor', '1');
  if (isZero) params.set('zero', '1');
  var qs = params.toString();
  return '/tools/communities/gap' + (qs ? '?' + qs : '');
}}

function updateGapCtaLink(isZero) {{
  document.getElementById('comm-gap-link').href = gapFormHref(isZero);
}}

function renderCommunities(list) {{
  var grid = document.getElementById('comm-grid');
  var empty = document.getElementById('comm-empty');
  var count = document.getElementById('comm-count');
  var pagination = document.getElementById('comm-pagination');
  updateGapCtaLink(list.length === 0);
  if (list.length === 0) {{
    grid.innerHTML = '';
    empty.style.display = 'block';
    empty.innerHTML = 'No communities match. <a href="' + gapFormHref(true) + '" style="font-weight:500;">Tell me what\\'s missing &rarr;</a>';
    count.textContent = '';
    pagination.style.display = 'none';
    pagination.innerHTML = '';
    return;
  }}
  empty.style.display = 'none';
  // Featured communities first, then alphabetical within each group.
  var sorted = list.slice().sort(function(a, b) {{
    if (a.featured && !b.featured) return -1;
    if (!a.featured && b.featured) return 1;
    return commEsc(a.name).localeCompare(commEsc(b.name));
  }});
  var totalPages = Math.ceil(sorted.length / COMM_PAGE_SIZE);
  if (commCurrentPage >= totalPages) commCurrentPage = totalPages - 1;
  if (commCurrentPage < 0) commCurrentPage = 0;
  var pageStart = commCurrentPage * COMM_PAGE_SIZE;
  var pageItems = sorted.slice(pageStart, pageStart + COMM_PAGE_SIZE);
  count.textContent = sorted.length + ' communit' + (sorted.length === 1 ? 'y' : 'ies')
    + (totalPages > 1 ? ' · showing ' + (pageStart + 1) + '–' + (pageStart + pageItems.length) : '');
  if (totalPages > 1) {{
    pagination.style.display = 'flex';
    pagination.innerHTML = '<button type="button" class="btn btn-ghost" onclick="goToCommPage(commCurrentPage - 1)"'
      + (commCurrentPage === 0 ? ' disabled' : '') + '>&larr; Back</button>'
      + '<span id="comm-pagination-label">Page ' + (commCurrentPage + 1) + ' of ' + totalPages + '</span>'
      + '<button type="button" class="btn btn-ghost" onclick="goToCommPage(commCurrentPage + 1)"'
      + (commCurrentPage >= totalPages - 1 ? ' disabled' : '') + '>Next &rarr;</button>';
  }} else {{
    pagination.style.display = 'none';
    pagination.innerHTML = '';
  }}
  grid.innerHTML = pageItems.map(function(c) {{
    var cats = (c.categories || []).map(function(x) {{
      return '<span class="comm-cat">' + commEsc(x) + '</span>';
    }}).join('');
    var metaParts = [commGeoLine(c)];
    if (c.access) metaParts.push(commVerify(c.access));
    if (c.sponsorship_type) {{
      metaParts.push(c.sponsorship_type === NEEDS_VERIFICATION
        ? commVerify(c.sponsorship_type)
        : commEsc(c.sponsorship_type) + (c.sponsor_name ? ' (' + commEsc(c.sponsor_name) + ')' : ''));
    }}
    var demoParts = [];
    if (c.demographic) demoParts.push(commVerify(c.demographic));
    if (c.notes) demoParts.push(commEsc(c.notes));
    if (c.cost_note) demoParts.push(commEsc(c.cost_note));
    var demoHtml = demoParts.join(' &middot; ');
    var featuredBadge = c.featured
      ? '<span style="font-size:10px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;'
        + 'background:var(--coral);color:#fff;border-radius:5px;padding:2px 8px;flex-shrink:0;">Featured</span>'
      : '';
    var advisorStar = c.advisor ? '<span class="comm-star" title="Brian Weisberg is a formal advisor">&#9733;</span>' : '';
    var compareChecked = compareSelected.indexOf(c.id) !== -1;
    var compareDisabled = !compareChecked && compareSelected.length >= COMPARE_MAX;
    var costHtml = c.cost_band === NEEDS_VERIFICATION
      ? '<span class="comm-verify">Needs verification</span>'
      : '<span class="comm-cost">' + commEsc(c.cost_band) + '</span>';
    var fullProfileLink = '<a class="comm-full-link" href="/tools/communities/' + commEsc(c.slug)
      + '" target="_blank" rel="noopener">Full profile &rarr;</a>';
    return '<article class="comm-card' + (c.featured ? ' comm-card-featured' : '') + '" data-comm-id="' + c.id + '">'
      + '<div style="display:flex;align-items:flex-start;justify-content:space-between;gap:12px;margin-bottom:2px;">'
      + '<div style="display:flex;align-items:center;gap:6px;min-width:0;flex-wrap:wrap;">'
      + commLogoBox(c.name, c.logo_url, 28)
      + featuredBadge + advisorStar
      + '<a class="comm-name" href="/tools/communities/' + commEsc(c.slug) + '" target="_blank" rel="noopener">' + commEsc(c.name) + '</a>'
      + '</div>'
      + costHtml
      + '</div>'
      + '<p class="comm-meta">' + metaParts.join(' &middot; ') + '</p>'
      + '<p class="comm-demo">' + demoHtml + '</p>'
      // Cats and the profile-link/compare row are split into two always-separate
      // rows (same fix as the Software directory's .tool-cats, webapp/app.py:4949-4951)
      // rather than sharing one flex row — a multi-badge category set wrapping to
      // 2 lines on one card and 1 on its neighbor used to break the uniform height
      // the clamps above are meant to guarantee.
      + '<div style="margin-top:auto;">'
      + '<div class="comm-cats">' + cats + '</div>'
      + '<div style="display:flex;align-items:center;gap:12px;margin-top:10px;">' + fullProfileLink
      + '<label class="comm-compare-label"' + (compareDisabled ? ' style="opacity:.45;"' : '') + '>'
      + '<input type="checkbox" class="comm-compare-cb" data-id="' + c.id + '"'
      + (compareChecked ? ' checked' : '') + (compareDisabled ? ' disabled' : '')
      + ' onchange="toggleCompareSelect(this)"> Compare</label>'
      + '</div>'
      + '</div>'
      + '</article>';
  }}).join('');
}}

function commFiltered() {{
  var q = (document.getElementById('comm-search').value || '').toLowerCase();
  var accessType = document.getElementById('comm-access').value;
  return ALL_COMMUNITIES.filter(function(c) {{
    if (accessType && accessBucket(c.access) !== accessType) return false;
    if (activeCommCost && c.cost_band !== activeCommCost) return false;
    if (commAdvisorOnly && !c.advisor) return false;
    if (activeCommCats.size > 0) {{
      var cats = c.categories || [];
      var hit = false;
      for (var i = 0; i < cats.length; i++) {{ if (activeCommCats.has(cats[i])) {{ hit = true; break; }} }}
      if (!hit && activeCommCats.has('__uncategorized__') && cats.length === 0) hit = true;
      if (!hit) return false;
    }}
    if (!q) return true;
    return (c.name + ' ' + c.demographic + ' ' + c.notes + ' ' + (c.local_markets || '') + ' ' + (c.categories || []).join(' ')).toLowerCase().indexOf(q) !== -1;
  }});
}}

function syncCommButtons() {{
  document.querySelectorAll('.ccat-btn[data-cat]').forEach(function(b) {{
    var c = b.dataset.cat;
    b.classList.toggle('ccat-active', c === '' ? activeCommCats.size === 0 : activeCommCats.has(c));
  }});
  document.querySelectorAll('.ccat-btn[data-cost]').forEach(function(b) {{
    var c = b.dataset.cost;
    b.classList.toggle('ccat-active', c === '' ? activeCommCost === '' : activeCommCost === c);
  }});
  var ab = document.getElementById('comm-advisor-btn');
  if (ab) ab.classList.toggle('ccat-active', commAdvisorOnly);
}}

function toggleCommAdvisor() {{
  commAdvisorOnly = !commAdvisorOnly;
  commCurrentPage = 0;
  syncCommButtons();
  renderCommunities(commFiltered());
}}

function filterCommCat(btn) {{
  var cat = btn.dataset.cat;
  if (cat === '') {{
    activeCommCats.clear();
  }} else if (activeCommCats.has(cat)) {{
    activeCommCats.delete(cat);
  }} else {{
    activeCommCats.add(cat);
  }}
  commCurrentPage = 0;
  syncCommButtons();
  renderCommunities(commFiltered());
}}

function filterCommCost(btn) {{
  activeCommCost = btn.dataset.cost;
  commCurrentPage = 0;
  syncCommButtons();
  renderCommunities(commFiltered());
}}

function filterCommunities() {{ commCurrentPage = 0; renderCommunities(commFiltered()); }}

function updateCompareBar() {{
  var bar = document.getElementById('comm-compare-bar');
  var count = document.getElementById('comm-compare-count');
  var link = document.getElementById('comm-compare-link');
  if (compareSelected.length === 0) {{
    bar.style.display = 'none';
    return;
  }}
  bar.style.display = 'flex';
  count.textContent = compareSelected.length + ' of ' + COMPARE_MAX + ' selected';
  link.href = '/tools/communities/compare?ids=' + compareSelected.join(',');
  if (compareSelected.length < 2) {{
    link.classList.add('comm-compare-link-disabled');
    link.style.pointerEvents = 'none';
    link.style.opacity = '.5';
  }} else {{
    link.classList.remove('comm-compare-link-disabled');
    link.style.pointerEvents = '';
    link.style.opacity = '';
  }}
}}

function toggleCompareSelect(cb) {{
  var id = parseInt(cb.dataset.id, 10);
  var msg = document.getElementById('comm-compare-msg');
  if (cb.checked) {{
    if (compareSelected.length >= COMPARE_MAX) {{
      cb.checked = false;
      return;
    }}
    compareSelected.push(id);
    msg.textContent = '';
  }} else {{
    compareSelected = compareSelected.filter(function(x) {{ return x !== id; }});
    msg.textContent = '';
  }}
  updateCompareBar();
  renderCommunities(commFiltered());
  if (compareSelected.length >= COMPARE_MAX) {{
    document.getElementById('comm-compare-msg').textContent = 'You can compare up to ' + COMPARE_MAX + ' communities at once. Remove one to add another.';
  }}
}}

function clearCompareSelection() {{
  compareSelected = [];
  document.getElementById('comm-compare-msg').textContent = '';
  updateCompareBar();
  renderCommunities(commFiltered());
}}

function goToCommPage(page) {{
  commCurrentPage = page;
  renderCommunities(commFiltered());
  document.getElementById('comm-grid').scrollIntoView({{behavior: 'smooth', block: 'start'}});
}}

renderCommunities(ALL_COMMUNITIES);
</script>"""
    return HTMLResponse(_page("Communities—Brian Weisberg", "CFO Toolbox", body, role=_role(request)))


def _community_geo_line(c: dict) -> str:
    """Python mirror of the /tools/communities card's commGeoLine JS helper,
    for server-rendering the same geography summary on the profile page.
    An unresearched reach must return the verification flag rather than
    falling through to the "no local_markets" branch below, which would
    otherwise render a guessed "National · online" as if it were confirmed."""
    if c.get("reach") == _NEEDS_VERIFICATION:
        return "Needs verification"
    local_markets = (c.get("local_markets") or "").strip()
    reach = c.get("reach") or "National"
    if reach == "Regional":
        return local_markets if local_markets else "Regional"
    if not local_markets:
        return "Global" if reach == "Global" else "National · online"
    return f"{reach} · {local_markets}"


