@app.post("/tools/submit")
async def tools_submit(request: Request, background_tasks: BackgroundTasks):
    if not _is_member(request):
        return _login_redirect(request)
    form = await request.form()
    name = (form.get("name") or "").strip()
    url = (form.get("url") or "").strip()
    description = (form.get("description") or "").strip()
    categories = [v.strip() for v in form.getlist("categories") if v.strip()]
    submitted_by = (form.get("submitted_by") or "").strip()
    if not (name and url and description and submitted_by):
        raise HTTPException(status_code=400, detail="Name, URL, description, and email are required.")
    from linklib.email_utils import send_notification_email, send_tool_submission_confirmation_email, default_notify_email
    lib = _lib()
    try:
        # Member submissions are a quick 1-2 sentence pitch, not a full profile
        # write-up — use it as the initial summary too (short text is already
        # the right shape for the directory card) until an admin reviews and
        # regenerates a fuller description/summary from the edit page before approving.
        tool_id = lib.add_tool(name, description, url, categories, submitted_by=submitted_by, approved=0,
                                summary=description)
        notify_to = os.environ.get("LINKLIB_CONTACT_EMAIL") or default_notify_email()
        if notify_to:
            _send_email_safely(
                lib, "tool_submission", send_notification_email,
                notify_to,
                subject=f"Tool submission: {name}",
                body=(f"Submitted by: {submitted_by}\n\n{name}\n{url}\n\n{description}\n\n"
                      f"Review at /admin/tools."),
                notification_type="tool_submission",
            )
        _send_email_safely(
            lib, "tool_submission_confirmation", send_tool_submission_confirmation_email,
            to=submitted_by, tool_name=name, tool_url=url, description=description,
            subject_template=lib.get_setting("tool_submission_subject_template") or None,
            body_template=lib.get_setting("tool_submission_body_template") or None,
            signoff=lib.get_setting("tool_submission_signoff") or None,
        )
    finally:
        lib.close()
    background_tasks.add_task(_run_tool_research, tool_id)
    return RedirectResponse("/tools/submit?submitted=1", status_code=303)


@app.get("/admin/contacts", response_class=HTMLResponse)
def admin_contacts(request: Request):
    if not _is_authed(request):
        return _login_redirect(request)
    lib = _lib()
    try:
        contacts = lib.list_contacts()
        audit_rows = lib.list_contact_audit_log(limit=100)
        # Viewing the page clears the Inbox badge — the next badge count is
        # only submissions newer than this visit.
        lib.set_setting("admin_viewed_contacts", datetime.now(timezone.utc).isoformat())
    finally:
        lib.close()
    def _contact_message_cell(message: str) -> str:
        """A long or multi-line submission otherwise dominates the row —
        show a short single-line preview, expandable to the full message,
        so the table stays scannable."""
        PREVIEW_LEN = 140
        flat = " ".join(message.split())
        if len(flat) <= PREVIEW_LEN and "\n" not in message:
            return f'<td style="padding:10px 12px;border-bottom:1px solid var(--line);white-space:pre-wrap;">{_esc(message)}</td>'
        preview = flat[:PREVIEW_LEN].rstrip() + "…" if len(flat) > PREVIEW_LEN else flat
        return (
            f'<td style="padding:10px 12px;border-bottom:1px solid var(--line);">'
            f'<details><summary style="cursor:pointer;color:var(--ink-soft);display:flex;align-items:baseline;gap:6px;">'
            f'<span class="disclosure-caret" style="font-size:11px;">&#9654;</span>{_esc(preview)}</summary>'
            f'<div style="white-space:pre-wrap;margin-top:8px;color:var(--ink-soft);">{_esc(message)}</div></details></td>'
        )

    rows = "".join(
        f"""<tr>
          <td style="padding:10px 12px;border-bottom:1px solid var(--line);"><input type="checkbox" name="ids" value="{c['id']}" class="contact-row-cb"></td>
          <td style="padding:10px 12px;border-bottom:1px solid var(--line);white-space:nowrap;">{_esc(c['created_at'][:10])}</td>
          <td style="padding:10px 12px;border-bottom:1px solid var(--line);">{_esc(c['name'])}</td>
          <td style="padding:10px 12px;border-bottom:1px solid var(--line);">{_esc(c['email'])}</td>
          {_contact_message_cell(c['message'])}
          <td style="padding:10px 12px;border-bottom:1px solid var(--line);white-space:nowrap;">
            <button type="submit" name="single_id" value="{c['id']}" class="btn btn-ghost"
              style="font-size:12px;padding:4px 12px;color:#b91c1c;border-color:#fca5a5;"
              onclick="return confirm('Delete this submission?');">Delete</button>
          </td>
        </tr>"""
        for c in contacts
    ) or '<tr><td colspan="6" style="padding:20px;color:var(--muted);">No submissions yet.</td></tr>'
    from linklib.email_utils import is_configured as _email_configured, default_notify_email
    notify_to = os.environ.get("LINKLIB_CONTACT_EMAIL") or default_notify_email()
    email_status = (
        f'<div style="background:var(--seafoam-wash);border:1px solid var(--seafoam);border-radius:10px;padding:14px 18px;margin:16px 0;font-size:14px;line-height:1.5;">'
        f'Email notifications are <strong>on</strong>&mdash;new submissions are emailed to <code>{_esc(notify_to)}</code>.</div>'
        if _email_configured() else
        '<div style="background:var(--coral-wash);border:1px solid var(--coral);border-radius:10px;padding:14px 18px;margin:16px 0;font-size:14px;line-height:1.5;">'
        'Email notifications are <strong>off</strong>&mdash;set the <code>GOOGLE_OAUTH_*</code> vars '
        '(shared with the Drive backup) + <code>LINKLIB_FROM_EMAIL</code> (and optionally '
        '<code>LINKLIB_CONTACT_EMAIL</code>) to enable them. Until then, check this page manually.</div>'
    )
    audit_html = "".join(
        f"""<tr>
          <td style="padding:8px 12px;border-bottom:1px solid var(--line);white-space:nowrap;font-size:13px;">{_esc(a['created_at'][:16].replace('T',' '))}</td>
          <td style="padding:8px 12px;border-bottom:1px solid var(--line);font-size:13px;">{_esc(a['admin_username'] or 'admin')}</td>
          <td style="padding:8px 12px;border-bottom:1px solid var(--line);font-size:13px;">{'Bulk delete' if a['item_id'] is None else 'Delete'}</td>
          <td style="padding:8px 12px;border-bottom:1px solid var(--line);font-size:13px;color:var(--ink-soft);">{_esc(a['detail'])}</td>
        </tr>"""
        for a in audit_rows
    ) or '<tr><td colspan="4" style="padding:16px;color:var(--muted);font-size:13px;">No deletions yet.</td></tr>'
    body = f"""<div class="page page-admin">
<p style="margin:0 0 4px;"><a href="/admin" style="font-size:13px;color:var(--muted);">&larr; Admin</a></p>
<h1>Contact submissions</h1>
{email_status}
<form method="post" action="/admin/contacts/delete">
<div style="display:flex;align-items:center;gap:12px;margin:24px 0 -8px;">
  <button type="submit" class="btn btn-ghost" style="font-size:13px;padding:6px 16px;"
    onclick="return document.querySelectorAll('.contact-row-cb:checked').length &amp;&amp; confirm('Delete ' + document.querySelectorAll('.contact-row-cb:checked').length + ' selected submission(s)?');">Delete selected</button>
</div>
<table style="width:100%;border-collapse:collapse;background:#fff;border-radius:12px;border:1px solid var(--line);overflow:hidden;margin-top:12px;">
<thead><tr style="background:var(--accent-light);">
  <th style="padding:10px 12px;text-align:left;font-size:13px;"><input type="checkbox" id="contact-select-all" onchange="document.querySelectorAll('.contact-row-cb').forEach(cb => cb.checked = this.checked);"></th>
  <th style="padding:10px 12px;text-align:left;font-size:13px;">Date</th>
  <th style="padding:10px 12px;text-align:left;font-size:13px;">Name</th>
  <th style="padding:10px 12px;text-align:left;font-size:13px;">Email</th>
  <th style="padding:10px 12px;text-align:left;font-size:13px;">Message</th>
  <th style="padding:10px 12px;text-align:left;font-size:13px;"></th>
</tr></thead>
<tbody>{rows}</tbody>
</table>
</form>
<h2 style="font-size:16px;margin:40px 0 12px;">Deletion history</h2>
<table style="width:100%;border-collapse:collapse;background:#fff;border-radius:12px;border:1px solid var(--line);overflow:hidden;">
<thead><tr style="background:var(--accent-light);">
  <th style="padding:8px 12px;text-align:left;font-size:13px;">When</th>
  <th style="padding:8px 12px;text-align:left;font-size:13px;">Admin</th>
  <th style="padding:8px 12px;text-align:left;font-size:13px;">Action</th>
  <th style="padding:8px 12px;text-align:left;font-size:13px;">What was deleted</th>
</tr></thead>
<tbody>{audit_html}</tbody>
</table>
</div>"""
    return HTMLResponse(_page("Contacts—Admin", "Admin", body, authed=True))


@app.post("/admin/contacts/delete")
async def admin_contacts_delete(request: Request):
    if not _is_authed(request):
        return _login_redirect(request)
    form = await request.form()
    single_id = form.get("single_id")
    if single_id:
        ids = [int(single_id)] if single_id.strip().isdigit() else []
    else:
        ids = [int(v) for v in form.getlist("ids") if v.strip().isdigit()]
    lib = _lib()
    try:
        deleted = lib.soft_delete_contacts(ids)
        if len(deleted) == 1:
            c = deleted[0]
            _log_contact_audit(lib, request, c["id"], detail=f"{c['name']} <{c['email']}>")
        elif len(deleted) > 1:
            summary = "; ".join(f"{c['name']} <{c['email']}>" for c in deleted)
            _log_contact_audit(lib, request, None, detail=f"{len(deleted)} submissions—{summary}")
    finally:
        lib.close()
    return RedirectResponse("/admin/contacts", status_code=303)


@app.get("/admin/email-failures", response_class=HTMLResponse)
def admin_email_failures(request: Request):
    if not _is_authed(request):
        return _login_redirect(request)
    lib = _lib()
    try:
        failures = lib.list_email_failures(pending_only=False)
    finally:
        lib.close()
    rows = "".join(
        f"""<tr>
          <td style="padding:10px 12px;border-bottom:1px solid var(--line);white-space:nowrap;">{_esc(f['created_at'][:16].replace('T',' '))}</td>
          <td style="padding:10px 12px;border-bottom:1px solid var(--line);white-space:nowrap;">{_esc(f['context'])}</td>
          <td style="padding:10px 12px;border-bottom:1px solid var(--line);white-space:pre-wrap;">{_esc(f['detail'])}</td>
          <td style="padding:10px 12px;border-bottom:1px solid var(--line);white-space:nowrap;">
            {'<span style="color:var(--muted);">dismissed</span>' if f['resolved_at'] else
             f'<form method="post" action="/admin/email-failures/{f["id"]}/dismiss" style="margin:0;">'
             f'<button type="submit" class="btn btn-ghost" style="font-size:12px;padding:4px 12px;">Dismiss</button></form>'}
          </td>
        </tr>"""
        for f in failures
    ) or '<tr><td colspan="4" style="padding:20px;color:var(--muted);">No failed sends recorded.</td></tr>'
    body = f"""<div class="page page-admin">
<p style="margin:0 0 4px;"><a href="/admin" style="font-size:13px;color:var(--muted);">&larr; Admin</a></p>
<h1>Email delivery failures</h1>
<p style="color:var(--muted);margin:-6px 0 6px;">Every outbound email is best-effort—contact form, tool submissions, welcome emails, password resets, warm intros. The underlying record always saves even if the send fails.</p>
<p style="color:var(--muted);margin:0 0 18px;">A failure lands here instead of just a server log, so it never goes unnoticed.</p>
<table style="width:100%;border-collapse:collapse;background:#fff;border-radius:12px;border:1px solid var(--line);overflow:hidden;">
<thead><tr style="background:var(--accent-light);">
  <th style="padding:10px 12px;text-align:left;font-size:13px;">When</th>
  <th style="padding:10px 12px;text-align:left;font-size:13px;">Flow</th>
  <th style="padding:10px 12px;text-align:left;font-size:13px;">Error</th>
  <th style="padding:10px 12px;text-align:left;font-size:13px;"></th>
</tr></thead>
<tbody>{rows}</tbody>
</table>
</div>"""
    return HTMLResponse(_page("Email failures—Admin", "Admin", body, authed=True))


@app.post("/admin/email-failures/{failure_id}/dismiss")
def admin_email_failure_dismiss(request: Request, failure_id: int):
    if not _is_authed(request):
        return _login_redirect(request)
    lib = _lib()
    try:
        lib.dismiss_email_failure(failure_id)
    finally:
        lib.close()
    return RedirectResponse("/admin/email-failures", status_code=303)


# Shared column-picker + bulk-edit UI for the Communities and Software admin
# tables. Both are plain server-rendered tables (no client framework), so the
# picker toggles column visibility via data-col attributes and the bulk-edit
# flow is fetch()-based against a per-table POST route — same no-reload
# pattern as saveCommunityWeights() above. Field lists differ per table
# (_COMMUNITY_BULK_FIELDS / _SOFTWARE_BULK_FIELDS below); the JS is generic
# over a "table key" so both pages share one script block.
_ADMIN_BULK_EDIT_JS = """
function initColPicker(tableKey, cols) {
  var stored = localStorage.getItem('cfo_admin_cols_' + tableKey);
  if (!stored) return;
  var active;
  try { active = JSON.parse(stored); } catch (e) { return; }
  cols.forEach(function(col) {
    var visible = active.indexOf(col) !== -1;
    document.querySelectorAll('[data-col="' + tableKey + ':' + col + '"]').forEach(function(el) {
      el.style.display = visible ? '' : 'none';
    });
    var cb = document.getElementById('colpick-' + tableKey + '-' + col);
    if (cb) cb.checked = visible;
  });
}
function toggleColumn(tableKey, col, checked, allCols) {
  document.querySelectorAll('[data-col="' + tableKey + ':' + col + '"]').forEach(function(el) {
    el.style.display = checked ? '' : 'none';
  });
  var stored = localStorage.getItem('cfo_admin_cols_' + tableKey);
  var active;
  try { active = stored ? JSON.parse(stored) : allCols.slice(); } catch (e) { active = allCols.slice(); }
  if (checked && active.indexOf(col) === -1) active.push(col);
  if (!checked) active = active.filter(function(c) { return c !== col; });
  localStorage.setItem('cfo_admin_cols_' + tableKey, JSON.stringify(active));
}
function updateBulkButton(tableKey) {
  var n = document.querySelectorAll('.' + tableKey + '-row-cb:checked').length;
  var btn = document.getElementById(tableKey + '-bulk-btn');
  if (btn) { btn.disabled = n === 0; btn.textContent = 'Edit selected (' + n + ')'; }
  var delBtn = document.getElementById(tableKey + '-bulk-delete-btn');
  if (delBtn) { delBtn.disabled = n === 0; delBtn.textContent = 'Delete selected (' + n + ')'; }
}
function selectAllRows(tableKey, checked) {
  // Only touch rows the sort/filter toolbar (applySortFilter) currently
  // shows — a filtered-out <tr> is display:none, not removed from the DOM,
  // so "select all" must skip it or it'd silently select hidden rows the
  // admin never saw checked.
  document.querySelectorAll('.' + tableKey + '-row-cb').forEach(function(cb) {
    var row = cb.closest('tr');
    if (row && row.style.display === 'none') return;
    cb.checked = checked;
  });
  updateBulkButton(tableKey);
}
function openBulkPanel(tableKey) {
  if (document.querySelectorAll('.' + tableKey + '-row-cb:checked').length === 0) return;
  document.getElementById(tableKey + '-bulk-panel').style.display = 'block';
  document.getElementById(tableKey + '-bulk-step1').style.display = 'block';
  document.getElementById(tableKey + '-bulk-step2').style.display = 'none';
  bulkFieldChanged(tableKey);
}
function closeBulkPanel(tableKey) {
  document.getElementById(tableKey + '-bulk-panel').style.display = 'none';
}
function bulkFieldChanged(tableKey) {
  var field = document.getElementById(tableKey + '-bulk-field').value;
  document.querySelectorAll('#' + tableKey + '-bulk-values > div').forEach(function(el) {
    el.style.display = (el.getAttribute('data-field') === field) ? 'block' : 'none';
  });
}
function bulkValueLabel(tableKey, field) {
  var container = document.querySelector('#' + tableKey + '-bulk-values [data-field="' + field + '"]');
  if (!container) return '';
  var sel = container.querySelector('select');
  if (sel) return sel.options[sel.selectedIndex].textContent;
  var multi = container.querySelectorAll('input[data-multi]');
  if (multi.length) {
    var chosen = Array.prototype.filter.call(multi, function(c) { return c.checked; })
      .map(function(c) { return c.getAttribute('data-label') || c.value; });
    return chosen.length ? chosen.join(', ') : '(none)';
  }
  var cb = container.querySelector('input[type="checkbox"]');
  if (cb) return cb.checked ? 'Yes' : 'No';
  return '';
}
function reviewBulkEdit(tableKey, fieldLabels) {
  var field = document.getElementById(tableKey + '-bulk-field').value;
  var n = document.querySelectorAll('.' + tableKey + '-row-cb:checked').length;
  var label = fieldLabels[field] || field;
  var value = bulkValueLabel(tableKey, field);
  document.getElementById(tableKey + '-bulk-summary').textContent =
    'Set "' + label + '" = "' + value + '" on ' + n + ' row' + (n === 1 ? '' : 's') + '.';
  document.getElementById(tableKey + '-bulk-step1').style.display = 'none';
  document.getElementById(tableKey + '-bulk-step2').style.display = 'block';
}
function backToBulkEdit(tableKey) {
  document.getElementById(tableKey + '-bulk-step1').style.display = 'block';
  document.getElementById(tableKey + '-bulk-step2').style.display = 'none';
}
async function submitBulkEdit(tableKey, url) {
  var ids = Array.prototype.map.call(document.querySelectorAll('.' + tableKey + '-row-cb:checked'), function(cb) { return parseInt(cb.value, 10); });
  var field = document.getElementById(tableKey + '-bulk-field').value;
  var container = document.querySelector('#' + tableKey + '-bulk-values [data-field="' + field + '"]');
  var value;
  var sel = container.querySelector('select');
  var multi = container.querySelectorAll('input[data-multi]');
  var cb = container.querySelector('input[type="checkbox"]:not([data-multi])');
  if (sel) {
    value = sel.value;
  } else if (multi.length) {
    value = Array.prototype.filter.call(multi, function(c) { return c.checked; }).map(function(c) { return c.value; });
  } else if (cb) {
    value = cb.checked ? '1' : '0';
  }
  var btn = document.getElementById(tableKey + '-bulk-confirm-btn');
  btn.disabled = true; btn.textContent = 'Applying…';
  try {
    var r = await fetch(url, {
      method: 'POST', headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({ids: ids, field: field, value: value})
    });
    if (!r.ok) throw new Error();
    window.location.reload();
  } catch (e) {
    document.getElementById(tableKey + '-bulk-summary').textContent = 'Save failed—try again.';
    btn.disabled = false; btn.textContent = 'Apply';
  }
}
async function openDeleteSelectedPanel(tableKey) {
  var ids = Array.prototype.map.call(document.querySelectorAll('.' + tableKey + '-row-cb:checked'), function(cb) { return parseInt(cb.value, 10); });
  if (!ids.length) return;
  document.getElementById(tableKey + '-delete-panel').style.display = 'block';
  var body = document.getElementById(tableKey + '-delete-body');
  body.innerHTML = '<p style="font-size:13px;color:var(--muted);">Checking for competitor references…</p>';
  var confirmBtn = document.getElementById(tableKey + '-delete-confirm-btn');
  confirmBtn.disabled = true; confirmBtn.textContent = 'Delete';
  try {
    var r = await fetch('/admin/tools/' + tableKey + '/bulk-delete-check', {
      method: 'POST', headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({ids: ids})
    });
    var d = await r.json();
    if (!r.ok || !d.ok) throw new Error();
    renderDeleteSelectedPanel(tableKey, ids, d);
  } catch (e) {
    body.innerHTML = '<p style="font-size:13px;color:#b91c1c;">Couldn\\'t load delete preview—try again.</p>';
  }
}
function renderDeleteSelectedPanel(tableKey, ids, d) {
  var esc = function(s) { return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); };
  var names = d.tools.map(function(t) { return '<li>' + esc(t.name) + '</li>'; }).join('');
  var warnHtml = '';
  if (d.warnings && d.warnings.length) {
    var items = d.warnings.map(function(w) {
      return '<li><strong>' + esc(w.name) + '</strong> is listed as a competitor on: ' + w.referenced_by.map(esc).join(', ') + '</li>';
    }).join('');
    warnHtml = '<div style="background:#fee2e2;border:1px solid #fca5a5;border-radius:8px;padding:10px 14px;margin:12px 0;font-size:13px;">' +
      '<strong>Heads up:</strong> deleting these will remove them from other tools&rsquo; competitor lists:' +
      '<ul style="margin:6px 0 0;padding-left:18px;">' + items + '</ul></div>';
  }
  document.getElementById(tableKey + '-delete-body').innerHTML =
    '<p style="font-size:14px;margin:0 0 8px;">Delete these ' + d.tools.length + ' tool' + (d.tools.length === 1 ? '' : 's') + '?</p>' +
    '<ul style="margin:0 0 8px;padding-left:18px;font-size:14px;">' + names + '</ul>' + warnHtml;
  var btn = document.getElementById(tableKey + '-delete-confirm-btn');
  btn.disabled = false; btn.textContent = 'Delete ' + d.tools.length + ' tool' + (d.tools.length === 1 ? '' : 's');
  btn.onclick = function() { submitBulkDelete(tableKey, ids); };
}
async function submitBulkDelete(tableKey, ids) {
  var btn = document.getElementById(tableKey + '-delete-confirm-btn');
  btn.disabled = true; btn.textContent = 'Deleting…';
  try {
    var r = await fetch('/admin/tools/' + tableKey + '/bulk-delete', {
      method: 'POST', headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({ids: ids})
    });
    if (!r.ok) throw new Error();
    window.location.reload();
  } catch (e) {
    btn.disabled = false; btn.textContent = 'Delete failed—try again';
  }
}
function closeDeleteSelectedPanel(tableKey) {
  document.getElementById(tableKey + '-delete-panel').style.display = 'none';
}
"""


def _admin_column_picker_html(table_key: str, columns: list[tuple[str, str]]) -> str:
    """columns: (col_key, label) pairs, all default-visible. Toggled client-side
    via data-col="{table_key}:{col_key}" on the corresponding <th>/<td>s and
    persisted to localStorage by toggleColumn() in _ADMIN_BULK_EDIT_JS."""
    # json.dumps() quotes with ", same as the onchange="" attribute itself—
    # unescaped, that closes the attribute early at the first array element
    # and leaves toggleColumn's 4th argument truncated, so the checkbox's
    # onchange handler never actually runs. _esc() turns those into &quot;
    # so the attribute parses whole.
    checks = "".join(
        f'<label style="display:flex;align-items:center;gap:6px;font-size:13px;cursor:pointer;">'
        f'<input type="checkbox" id="colpick-{table_key}-{key}" checked '
        f'onchange="toggleColumn(\'{table_key}\',\'{key}\',this.checked,{_esc(json.dumps([k for k, _ in columns]))})"> {_esc(label)}</label>'
        for key, label in columns
    )
    return f"""<details style="margin:0 0 12px;">
  <summary style="cursor:pointer;font-size:13px;color:var(--muted);display:inline-flex;align-items:center;gap:5px;">Columns <span class="disclosure-caret" style="font-size:12px;">&#9654;</span></summary>
  <div style="display:flex;flex-wrap:wrap;gap:10px 16px;margin-top:8px;padding:10px 14px;border:1px solid var(--line);border-radius:8px;background:var(--surface);max-width:520px;">
    {checks}
  </div>
</details>"""


def _admin_bulk_panel_html(table_key: str, post_url: str, fields: list[dict], category_options: list[dict] | None = None,
                            show_delete_button: bool = False) -> str:
    """fields: [{key, label, kind: 'select'|'checkbox'|'multi', options?}, ...].
    'multi' fields render a category_options checkbox grid and always replace
    (not add/remove) the target rows' category set with the checked ones.

    show_delete_button adds a "Delete selected" button next to "Edit selected"
    plus its own confirm panel (openDeleteSelectedPanel/renderDeleteSelectedPanel/
    submitBulkDelete in _ADMIN_BULK_EDIT_JS), wired to
    POST /admin/tools/{table_key}/bulk-delete-check and .../bulk-delete. Opt-in
    per table (currently just Software) rather than default-on for every
    bulk-panel caller."""
    field_options_html = "".join(f'<option value="{f["key"]}">{_esc(f["label"])}</option>' for f in fields)

    def _value_control(f: dict) -> str:
        if f["kind"] == "select":
            opts = "".join(f'<option value="{_esc(o)}">{_esc(o)}</option>' for o in f["options"])
            return (f'<div data-field="{f["key"]}" style="display:none;">'
                    f'<select id="{table_key}-bulk-val-{f["key"]}" style="width:100%;padding:8px 10px;border:1px solid var(--line);border-radius:8px;">{opts}</select></div>')
        if f["kind"] == "checkbox":
            return (f'<div data-field="{f["key"]}" style="display:none;">'
                    f'<label style="display:flex;align-items:center;gap:8px;font-size:14px;cursor:pointer;">'
                    f'<input type="checkbox" id="{table_key}-bulk-val-{f["key"]}"> {_esc(f["label"])}</label></div>')
        if f["kind"] == "multi":
            opts = "".join(
                f'<label style="display:flex;align-items:center;gap:6px;font-size:13px;cursor:pointer;">'
                f'<input type="checkbox" data-multi value="{_esc(c["name"])}" data-label="{_esc(c["name"])}"> {_esc(c["name"])}</label>'
                for c in (category_options or [])
            ) or '<p style="grid-column:1/-1;font-size:13px;color:var(--muted);margin:0;">No categories yet.</p>'
            return f'<div data-field="{f["key"]}" style="display:none;"><div style="display:grid;grid-template-columns:1fr 1fr;gap:6px;">{opts}</div></div>'
        return ""

    values_html = "".join(_value_control(f) for f in fields)
    labels_json = json.dumps({f["key"]: f["label"] for f in fields})

    delete_button_html = (
        f'<button type="button" id="{table_key}-bulk-delete-btn" class="btn btn-ghost" disabled '
        f'style="font-size:13px;padding:6px 16px;color:#b91c1c;border-color:#fca5a5;" '
        f'onclick="openDeleteSelectedPanel(\'{table_key}\')">Delete selected (0)</button>'
        if show_delete_button else ""
    )
    delete_panel_html = (
        f"""<div id="{table_key}-delete-panel" style="display:none;border:1px solid #fca5a5;border-radius:12px;padding:16px 18px;margin:0 0 20px;background:var(--surface);max-width:520px;">
  <div id="{table_key}-delete-body"></div>
  <div style="margin-top:14px;">
    <button type="button" id="{table_key}-delete-confirm-btn" class="btn" disabled
      style="font-size:13px;padding:6px 16px;background:#b91c1c;border-color:#b91c1c;">Delete</button>
    <button type="button" class="btn btn-ghost" style="font-size:13px;padding:6px 16px;margin-left:6px;"
      onclick="closeDeleteSelectedPanel('{table_key}')">Cancel</button>
  </div>
</div>""" if show_delete_button else ""
    )

    return f"""
<div style="margin:0 0 16px;display:flex;gap:10px;flex-wrap:wrap;">
  <button type="button" id="{table_key}-bulk-btn" class="btn btn-ghost" disabled
    style="font-size:13px;padding:6px 16px;" onclick="openBulkPanel('{table_key}')">Edit selected (0)</button>
  {delete_button_html}
</div>
<div id="{table_key}-bulk-panel" style="display:none;border:1px solid var(--line);border-radius:12px;padding:16px 18px;margin:0 0 20px;background:var(--surface);max-width:480px;">
  <div id="{table_key}-bulk-step1">
    <label style="display:block;font-size:13px;font-weight:600;color:var(--navy);margin-bottom:8px;">Field to update</label>
    <select id="{table_key}-bulk-field" onchange="bulkFieldChanged('{table_key}')" style="width:100%;padding:8px 10px;border:1px solid var(--line);border-radius:8px;margin-bottom:12px;">
      {field_options_html}
    </select>
    <div id="{table_key}-bulk-values">{values_html}</div>
    <div style="margin-top:14px;">
      <button type="button" class="btn" style="font-size:13px;padding:6px 16px;"
        onclick="reviewBulkEdit('{table_key}', {labels_json})">Review changes</button>
      <button type="button" class="btn btn-ghost" style="font-size:13px;padding:6px 16px;margin-left:6px;"
        onclick="closeBulkPanel('{table_key}')">Cancel</button>
    </div>
  </div>
  <div id="{table_key}-bulk-step2" style="display:none;">
    <p id="{table_key}-bulk-summary" style="font-size:14px;margin:0 0 14px;"></p>
    <button type="button" id="{table_key}-bulk-confirm-btn" class="btn" style="font-size:13px;padding:6px 16px;"
      onclick="submitBulkEdit('{table_key}', '{post_url}')">Apply</button>
    <button type="button" class="btn btn-ghost" style="font-size:13px;padding:6px 16px;margin-left:6px;"
      onclick="backToBulkEdit('{table_key}')">Back</button>
  </div>
</div>
{delete_panel_html}"""


# Client-side sort/filter for the same two approved-rows tables — no new route,
# since both tables already render in full (no pagination) and the column
# picker above proved the client-only, no-reload approach works fine for this
# admin audience. Sort/filter targets are read off data-* attributes stamped
# on each <tr> (see _admin_row_data_attrs) rather than the visible <td> text,
# so filtering doesn't break when a column is hidden by the picker.
_ADMIN_SORT_FILTER_JS = """
function applySortFilter(tableKey) {
  var tbody = document.getElementById(tableKey + '-approved-tbody');
  if (!tbody) return;
  var rows = Array.prototype.filter.call(tbody.querySelectorAll('tr[data-name]'), function() { return true; });
  if (!rows.length) return;

  var activeFilters = {};
  document.querySelectorAll('#' + tableKey + '-filter-scalars select').forEach(function(sel) {
    if (sel.value) activeFilters[sel.getAttribute('data-filter-field')] = sel.value;
  });
  var catBoxes = document.querySelectorAll('#' + tableKey + '-filter-categories input:checked');
  var activeCats = Array.prototype.map.call(catBoxes, function(c) { return c.value.toLowerCase(); });
  var searchBox = document.getElementById(tableKey + '-filter-search');
  var q = searchBox ? searchBox.value.trim().toLowerCase() : '';

  var visible = 0;
  rows.forEach(function(row) {
    var ok = true;
    Object.keys(activeFilters).forEach(function(field) {
      if ((row.getAttribute('data-' + field) || '') !== activeFilters[field]) ok = false;
    });
    if (ok && activeCats.length) {
      var rowCats = (row.getAttribute('data-categories') || '').split('|').filter(function(c) { return c; });
      var matched = activeCats.some(function(c) { return rowCats.indexOf(c) !== -1; })
        || (activeCats.indexOf('__uncategorized__') !== -1 && rowCats.length === 0);
      if (!matched) ok = false;
    }
    if (ok && q && (row.getAttribute('data-search') || '').indexOf(q) === -1) ok = false;
    row.style.display = ok ? '' : 'none';
    if (ok) visible++;
  });

  var sortSel = document.getElementById(tableKey + '-sort-field');
  var dirBtn = document.getElementById(tableKey + '-sort-dir');
  if (sortSel) {
    var field = sortSel.value;
    var dir = dirBtn ? dirBtn.getAttribute('data-dir') : 'asc';
    rows.sort(function(a, b) {
      var av = (a.getAttribute('data-' + field) || '').toLowerCase();
      var bv = (b.getAttribute('data-' + field) || '').toLowerCase();
      var cmp = av < bv ? -1 : av > bv ? 1 : 0;
      return dir === 'desc' ? -cmp : cmp;
    });
    rows.forEach(function(row) { tbody.appendChild(row); });
  }

  var countEl = document.getElementById(tableKey + '-sort-filter-count');
  if (countEl) countEl.textContent = 'Showing ' + visible + ' of ' + rows.length;
}
function toggleSortDir(tableKey) {
  var btn = document.getElementById(tableKey + '-sort-dir');
  var next = btn.getAttribute('data-dir') === 'asc' ? 'desc' : 'asc';
  btn.setAttribute('data-dir', next);
  btn.textContent = next === 'asc' ? 'Ascending' : 'Descending';
  applySortFilter(tableKey);
}
function resetSortFilter(tableKey) {
  document.querySelectorAll('#' + tableKey + '-filter-scalars select').forEach(function(sel) { sel.value = ''; });
  document.querySelectorAll('#' + tableKey + '-filter-categories input').forEach(function(cb) { cb.checked = false; });
  var searchBox = document.getElementById(tableKey + '-filter-search');
  if (searchBox) searchBox.value = '';
  var sortSel = document.getElementById(tableKey + '-sort-field');
  if (sortSel) sortSel.value = sortSel.options[0].value;
  var dirBtn = document.getElementById(tableKey + '-sort-dir');
  if (dirBtn) { dirBtn.setAttribute('data-dir', 'asc'); dirBtn.textContent = 'A \\u2192 Z'; }
  applySortFilter(tableKey);
}
"""


def _admin_row_data_attrs(fields: dict[str, str]) -> str:
    """fields: {attr_suffix: raw_value}. Renders data-{suffix}="{value}" pairs,
    lowercased for case-insensitive sort/filter comparison in _ADMIN_SORT_FILTER_JS.
    Category lists are passed pre-joined with '|'."""
    return " ".join(f'data-{k}="{_esc(v.lower())}"' for k, v in fields.items())


def _admin_sort_filter_toolbar_html(table_key: str, sort_fields: list[tuple[str, str]],
                                     scalar_filters: list[dict], category_options: list[dict] | None = None,
                                     category_style: str = "dropdown", search_placeholder: str | None = None) -> str:
    """sort_fields: (field_key, label) pairs, first is the default (Name, matching
    the tables' existing server-side ORDER BY). scalar_filters: [{key, label, options}].
    category_options: if given, adds an OR-matched category filter alongside the
    scalar (AND-matched) filters.

    category_style: 'dropdown' (default, a click-to-reveal <details> — kept as-is
    for existing callers) or 'pills' — always-visible, multi-select toggle pills
    mirroring the .tcat-btn pattern on the public /tools/software directory
    (same OR-within-categories, AND-with-everything-else semantics either way;
    only the affordance changes).

    search_placeholder: if given, adds a live text-search box (no submit button)
    that AND-filters against each row's data-search attribute (see
    _admin_row_data_attrs) alongside the category/scalar filters."""
    sort_options = "".join(f'<option value="{k}">{_esc(label)}</option>' for k, label in sort_fields)
    scalar_html = "".join(
        f'<select data-filter-field="{f["key"]}" onchange="applySortFilter(\'{table_key}\')" '
        f'style="padding:6px 10px;border:1px solid var(--line);border-radius:8px;font-size:13px;">'
        f'<option value="">{_esc(f["label"])}: All</option>'
        + "".join(f'<option value="{_esc(o.lower())}">{_esc(o)}</option>' for o in f["options"])
        + '</select>'
        for f in scalar_filters
    )
    category_html = ""
    pills_html = ""
    if category_options and category_style == "pills":
        boxes = "".join(
            f'<label class="admin-cat-pill">'
            f'<input type="checkbox" value="{_esc(c["name"])}" onchange="applySortFilter(\'{table_key}\')"> {_esc(c["name"])}</label>'
            for c in category_options
        )
        # "Uncategorized" is a hygiene filter (Phase J3), not a real category —
        # a reserved sentinel value the JS OR-matches against an empty
        # data-categories attribute instead of a category name (see
        # applySortFilter in _ADMIN_SORT_FILTER_JS).
        boxes += (f'<label class="admin-cat-pill">'
                  f'<input type="checkbox" value="__uncategorized__" onchange="applySortFilter(\'{table_key}\')"> Uncategorized</label>')
        # Collapsed by default (Phase J2) — same disclosure affordance as the
        # "Columns ▾" toggle above, just click-to-reveal rather than
        # always-visible, since admins have less use for the pill row than
        # public visitors browsing the directory.
        pills_html = (f'<details style="margin:-2px 0 12px;">'
                      f'<summary style="cursor:pointer;font-size:13px;color:var(--muted);display:inline-flex;'
                      f'align-items:center;gap:5px;">Categories <span class="disclosure-caret" style="font-size:12px;">&#9654;</span></summary>'
                      f'<div id="{table_key}-filter-categories" style="display:flex;flex-wrap:wrap;gap:8px;'
                      f'align-items:center;margin-top:10px;">{boxes}</div></details>'
                      '<style>.admin-cat-pill{display:inline-flex;align-items:center;gap:6px;font-size:13px;'
                      'font-weight:500;padding:6px 14px;border-radius:999px;border:1px solid var(--line);'
                      'color:var(--muted);cursor:pointer;white-space:nowrap;}'
                      '.admin-cat-pill:hover{background:var(--accent-light);color:var(--ink);}'
                      '.admin-cat-pill input{position:absolute;opacity:0;width:0;height:0;}'
                      '.admin-cat-pill:has(input:checked){background:var(--accent);color:#fff;border-color:var(--accent);}'
                      '</style>')
    elif category_options:
        boxes = "".join(
            f'<label style="display:flex;align-items:center;gap:5px;font-size:12px;cursor:pointer;white-space:nowrap;">'
            f'<input type="checkbox" value="{_esc(c["name"])}" onchange="applySortFilter(\'{table_key}\')"> {_esc(c["name"])}</label>'
            for c in category_options
        )
        category_html = (f'<details style="display:inline-block;"><summary style="cursor:pointer;font-size:13px;'
                          f'color:var(--muted);display:inline-flex;align-items:center;gap:5px;">Categories '
                          f'<span class="disclosure-caret" style="font-size:12px;">&#9654;</span></summary>'
                          f'<div id="{table_key}-filter-categories" style="display:flex;flex-wrap:wrap;gap:6px 12px;'
                          f'margin-top:8px;padding:10px 12px;border:1px solid var(--line);border-radius:8px;'
                          f'background:var(--surface);max-width:420px;">{boxes}</div></details>')
    search_html = ""
    if search_placeholder:
        search_html = (f'<input id="{table_key}-filter-search" type="search" '
                        f'placeholder="{_esc(search_placeholder)}" oninput="applySortFilter(\'{table_key}\')" '
                        'style="padding:6px 10px;border:1px solid var(--line);border-radius:8px;font-size:13px;'
                        'min-width:220px;">')
    return f"""{pills_html}<div style="display:flex;flex-wrap:wrap;align-items:center;gap:10px;margin:0 0 12px;">
  <label style="font-size:13px;color:var(--muted);">Sort by</label>
  <select id="{table_key}-sort-field" onchange="applySortFilter('{table_key}')"
    style="padding:6px 10px;border:1px solid var(--line);border-radius:8px;font-size:13px;">{sort_options}</select>
  <button type="button" id="{table_key}-sort-dir" data-dir="asc" onclick="toggleSortDir('{table_key}')"
    class="btn btn-ghost" style="font-size:13px;padding:5px 12px;">Ascending</button>
  <span style="width:1px;height:20px;background:var(--line);"></span>
  <div id="{table_key}-filter-scalars" style="display:flex;flex-wrap:wrap;gap:10px;">{scalar_html}</div>
  {search_html}
  {category_html}
  <button type="button" onclick="resetSortFilter('{table_key}')" class="btn btn-ghost" style="font-size:13px;padding:5px 12px;">Reset</button>
  <span id="{table_key}-sort-filter-count" style="font-size:13px;color:var(--muted);margin-left:auto;"></span>
</div>"""


@app.get("/admin/tools/software", response_class=HTMLResponse)
def admin_software(request: Request):
    if not _is_authed(request):
        return _login_redirect(request)
    lib = _lib()
    try:
        pending = [t for t in lib.list_tools(approved_only=False) if not t["approved"]]
        approved = [t for t in lib.list_tools(approved_only=True)]
        lead_counts = lib.get_tool_lead_counts()
        tool_categories = lib.list_tool_categories()
        n_name_dupes = len(lib.find_tool_name_duplicate_candidates())
    finally:
        lib.close()

    def _tool_row(t: dict) -> str:
        cats = ", ".join(t["categories"]) or "—"
        return f"""<tr>
          <td style="padding:10px 12px;border-bottom:1px solid var(--line);white-space:nowrap;">{_esc(t['created_at'][:10])}</td>
          <td style="padding:10px 12px;border-bottom:1px solid var(--line);font-weight:600;"><a href="{_esc(t['url'])}" target="_blank" rel="noopener" title="{_esc(t['url'])}">{_esc(t['name'])}</a></td>
          <td style="padding:10px 12px;border-bottom:1px solid var(--line);font-size:14px;">{_esc(t['description'])}</td>
          <td style="padding:10px 12px;border-bottom:1px solid var(--line);font-size:13px;color:var(--muted);">{_esc(cats)}</td>
          <td style="padding:10px 12px;border-bottom:1px solid var(--line);font-size:13px;color:var(--muted);">{_esc(t['submitted_by'] or '—')}</td>
          <td style="padding:10px 12px;border-bottom:1px solid var(--line);white-space:nowrap;">
            <form method="post" action="/admin/tools/{t['id']}/approve" style="display:inline;">
              <button class="btn" style="padding:6px 14px;font-size:13px;">Approve</button>
            </form>
            <form method="post" action="/admin/tools/{t['id']}/reject" style="display:inline;margin-left:6px;"
                  onsubmit="return confirm('Reject and delete this submission?');">
              <button class="btn btn-ghost" style="padding:5px 12px;font-size:13px;color:#b91c1c;border-color:#fca5a5;">Reject</button>
            </form>
          </td>
        </tr>"""

    def _approved_row(t: dict) -> str:
        cats = ", ".join(t["categories"]) or "—"
        n_leads = lead_counts.get(t["id"], 0)
        lead_badge = (f'<a href="/admin/tools/leads?tool_id={t["id"]}" '
                      f'style="display:inline-block;background:var(--coral);color:#fff;border-radius:5px;'
                      f'padding:2px 8px;font-size:11px;font-weight:700;text-decoration:none;white-space:nowrap;">'
                      f'{n_leads} intro{"s" if n_leads != 1 else ""}</a>') if n_leads else \
                     '<span style="font-size:12px;color:var(--muted);">0 intros</span>'
        featured_badge = '<span style="display:inline-block;font-size:11px;font-weight:700;background:var(--coral);color:#fff;border-radius:4px;padding:1px 6px;">Featured</span>' if t.get("promoted") else ""
        row_attrs = _admin_row_data_attrs({
            "name": t["name"], "promoted": "1" if t.get("promoted") else "0",
            "categories": "|".join(t["categories"]),
            "url": t["url"], "summary": t.get("summary") or "",
            # Zero-padded so the shared string sort in _ADMIN_SORT_FILTER_JS
            # orders "10" after "9" instead of before it.
            "intros": f"{n_leads:04d}",
            "search": f"{t['name']} {t['url']}",
        })
        # data-label on each <td> feeds the stacked-card layout at the
        # .admin-table-responsive breakpoint (see its CSS)—unused above that
        # breakpoint, where the table renders normally.
        return f"""<tr class="admin-table-row" {row_attrs}>
          <td class="admin-table-cell" style="padding:10px 12px;border-bottom:1px solid var(--line);"><input type="checkbox" name="ids" value="{t['id']}" class="software-row-cb" onchange="updateBulkButton('software')"></td>
          <td class="admin-table-cell" style="padding:10px 12px;border-bottom:1px solid var(--line);font-weight:600;max-width:200px;">
            <div style="display:flex;flex-wrap:wrap;align-items:center;gap:4px 6px;">
              <a href="{_esc(t['url'])}" target="_blank" rel="noopener" title="{_esc(t['url'])}">{_esc(t['name'])}</a>{featured_badge}
            </div>
          </td>
          <td data-col="software:summary" data-label="Short description" class="admin-table-cell" style="padding:10px 12px;border-bottom:1px solid var(--line);font-size:13px;color:var(--muted);min-width:260px;">{_esc(t.get('summary') or '—')}</td>
          <td data-col="software:categories" data-label="Categories" class="admin-table-cell" style="padding:10px 12px;border-bottom:1px solid var(--line);font-size:13px;color:var(--muted);">{_esc(cats)}</td>
          <td data-col="software:intros" data-label="Intros" class="admin-table-cell" style="padding:10px 12px;border-bottom:1px solid var(--line);">{lead_badge}</td>
          <td class="admin-table-cell admin-table-actions" data-label="Actions" style="padding:10px 12px;border-bottom:1px solid var(--line);">
            <div class="admin-table-actions-grid" style="display:grid;grid-template-columns:repeat(2,auto);gap:6px;">
              <a href="/tools/software/{t['slug']}/edit" target="_blank" rel="noopener" class="btn btn-ghost" style="padding:5px 12px;font-size:13px;text-align:center;">Edit</a>
              <form method="post" action="/admin/tools/{t['id']}/delete" style="margin:0;"
                    onsubmit="return confirm('Delete &quot;{_esc(t['name'])}&quot;? This removes it from the public directory.');">
                <input type="hidden" name="redirect_to" value="/admin/tools/software">
                <button type="submit" class="btn btn-ghost" style="width:100%;padding:5px 12px;font-size:13px;color:#b91c1c;border-color:#fca5a5;">Delete</button>
              </form>
            </div>
          </td>
        </tr>"""

    pending_rows = "".join(_tool_row(t) for t in pending) or \
        '<tr><td colspan="6" style="padding:20px;color:var(--muted);">No pending submissions.</td></tr>'
    approved_rows = "".join(_approved_row(t) for t in approved) or \
        '<tr><td colspan="7" style="padding:20px;color:var(--muted);">No approved software yet.</td></tr>'
    total_leads = sum(lead_counts.values())

    software_cols = [("summary", "Short description"), ("categories", "Categories"), ("intros", "Intros")]
    software_bulk_fields = [
        {"key": "categories", "label": "Categories", "kind": "multi"},
        {"key": "advisor", "label": "Formal advisor", "kind": "checkbox"},
        {"key": "promoted", "label": "Featured", "kind": "checkbox"},
        {"key": "warm_intro_enabled", "label": "Warm Intro enabled", "kind": "checkbox"},
    ]
    # Featured is a boolean/tag, not a sortable column—kept out of this list
    # entirely (see the Cost band/Access/etc. pattern on the Communities
    # table above, which likewise never lists its own Featured checkbox).
    software_sort_fields = [("name", "Name"), ("url", "URL"), ("summary", "Short description"), ("intros", "Intros")]

    body = f"""<script>{_ADMIN_BULK_EDIT_JS}{_ADMIN_SORT_FILTER_JS}</script>
<div class="page page-admin">
<p style="margin:0 0 4px;"><a href="/admin" style="font-size:13px;color:var(--muted);">&larr; Admin</a></p>
<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:4px;">
  <h1>Software</h1>
  <a href="/admin/tools/new" class="btn" style="font-size:14px;padding:8px 18px;">+ Add software</a>
</div>
<p style="margin:0 0 24px;">
  <a href="/tools/software" style="font-size:13px;color:var(--muted);">View public directory →</a>
  &nbsp;&middot;&nbsp;
  <a href="/admin/tools/leads" style="font-size:13px;color:var(--muted);">View all intros ({total_leads}) →</a>
  &nbsp;&middot;&nbsp;
  <a href="/admin/tools/name-duplicates" style="font-size:13px;color:{'#92400e' if n_name_dupes else 'var(--muted)'};font-weight:{'700' if n_name_dupes else '400'};">Check for name duplicates{f' ({n_name_dupes})' if n_name_dupes else ''} →</a>
</p>

<h2 style="font-size:16px;font-weight:600;margin:0 0 12px;">Pending submissions</h2>
<div style="overflow-x:auto;margin-bottom:40px;">
<table style="width:100%;border-collapse:collapse;background:#fff;border-radius:12px;border:1px solid var(--line);overflow:hidden;">
<thead><tr style="background:var(--accent-light);">
  <th style="padding:10px 12px;text-align:left;font-size:13px;">Date</th>
  <th style="padding:10px 12px;text-align:left;font-size:13px;">Name</th>
  <th style="padding:10px 12px;text-align:left;font-size:13px;">Description</th>
  <th style="padding:10px 12px;text-align:left;font-size:13px;">Categories</th>
  <th style="padding:10px 12px;text-align:left;font-size:13px;">Submitted by</th>
  <th style="padding:10px 12px;text-align:left;font-size:13px;">Actions</th>
</tr></thead>
<tbody>{pending_rows}</tbody>
</table>
</div>

<h2 style="font-size:16px;font-weight:600;margin:0 0 12px;">Approved software</h2>
{_admin_column_picker_html("software", software_cols)}
{_admin_sort_filter_toolbar_html("software", software_sort_fields, [], category_options=tool_categories,
                                  category_style="pills", search_placeholder="Search by name or URL…")}
{_admin_bulk_panel_html("software", "/admin/tools/software/bulk-edit", software_bulk_fields, category_options=tool_categories, show_delete_button=True)}
<div style="overflow-x:auto;">
<form id="software-approved-form">
<table class="admin-table-responsive" style="width:100%;border-collapse:collapse;background:#fff;border-radius:12px;border:1px solid var(--line);overflow:hidden;">
<thead><tr style="background:var(--accent-light);">
  <th style="padding:10px 12px;text-align:left;font-size:13px;"><input type="checkbox" onchange="selectAllRows('software',this.checked)"></th>
  <th style="padding:10px 12px;text-align:left;font-size:13px;">Name</th>
  <th data-col="software:summary" style="padding:10px 12px;text-align:left;font-size:13px;">Short description</th>
  <th data-col="software:categories" style="padding:10px 12px;text-align:left;font-size:13px;">Categories</th>
  <th data-col="software:intros" style="padding:10px 12px;text-align:left;font-size:13px;">Intros</th>
  <th style="padding:10px 12px;text-align:left;font-size:13px;">Actions</th>
</tr></thead>
<tbody id="software-approved-tbody">{approved_rows}</tbody>
</table>
</form>
</div>
<script>
initColPicker('software', {json.dumps([k for k, _ in software_cols])});
applySortFilter('software');
</script>

<p style="font-size:12px;color:var(--muted);margin:16px 0 0;">
  Editing <code>scripts/seed_tools.py</code> updates a tool&rsquo;s <strong>name</strong> and
  <strong>description</strong> here automatically on the next deploy. No manual re-seed needed.
  <strong>Categories, Advisor, Featured, and Warm Intro are database-only</strong>: edit them here
  (Full edit / Quick edit on <a href="/tools/software">/tools/software</a>), and this sync will never touch them.
</p>

<style>
/* Stacked-card responsive table (no equivalent pattern existed elsewhere in
   the codebase to reuse): below the breakpoint, rows become blocks and each
   cell gets a label from its data-label attribute instead of relying on a
   <thead> the layout no longer has room for. Column-picker visibility
   (toggleColumn, in _ADMIN_BULK_EDIT_JS) still works unchanged—it only ever
   toggled a per-cell inline display style, and that's exactly as meaningful
   in block layout as in table layout. Fixes the URL column wrapping badly
   and the Edit/Delete actions rendering unusably small on mobile.
*/
@media(max-width:700px){{
  .admin-table-responsive thead{{display:none;}}
  .admin-table-responsive, .admin-table-responsive tbody,
  .admin-table-responsive tr, .admin-table-responsive td{{display:block;width:100%;}}
  .admin-table-responsive tr{{border-bottom:2px solid var(--line);padding:10px 0;}}
  .admin-table-cell{{border-bottom:none!important;padding:6px 12px!important;}}
  .admin-table-cell[data-label]::before{{content:attr(data-label);display:block;
    font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:.05em;
    color:var(--muted);margin-bottom:3px;}}
  .admin-table-actions .admin-table-actions-grid{{grid-template-columns:1fr!important;}}
}}
</style>
</div>"""
    return HTMLResponse(_page("Software—CFO Toolbox Admin", "", body, authed=True))


# ---------------------------------------------------------------------------
# Name-based duplicate detection for the Software directory. Separate from
# the URL-based DuplicateURLError check above (blocking, exact-URL-match,
# enforced in linklib.db.add_tool/update_tool): this is an exact-match
# normalize_tool_name() sweep across every current tool, surfaced here as a
# reviewable list rather than enforced at save time (see the warn banner on
# /tools/software wired from the two save routes above for the save-time
# half). See linklib.db.normalize_tool_name for what "exact-match" covers
# (case, parentheticals, entity suffixes) and deliberately doesn't (spelling,
# spacing/hyphenation, or any fuzzy/distance-based matching).
# ---------------------------------------------------------------------------

@app.get("/admin/tools/name-duplicates", response_class=HTMLResponse)
def admin_tool_name_duplicates(request: Request, msg: str = ""):
    if not _is_authed(request):
        return _login_redirect(request)
    lib = _lib()
    try:
        candidates = lib.find_tool_name_duplicate_candidates()
        pending_merges = lib.pending_tool_name_merges()
        decisions = [d for d in lib.tool_name_dedupe_decisions(limit=40) if d["verdict"] == "dismissed"]
    finally:
        lib.close()

    banner = (f'<p style="background:#d1fae5;color:#065f46;border-radius:10px;padding:10px 16px;'
              f'font-size:14px;margin:-6px 0 16px;">{_esc(msg)}</p>' if msg else '')

    def _tool_cell(t: dict) -> str:
        approved_tag = '' if t["approved"] else ' <span style="font-size:11px;color:var(--muted);">(pending)</span>'
        return (f'<a href="/tools/software/{_esc(t["slug"])}/edit" style="font-weight:600;">{_esc(t["name"])}</a>{approved_tag}'
                f'<div style="font-size:12px;color:var(--muted);word-break:break-all;">{_esc(t["url"])}</div>')

    def _confirm(keep: dict, delete: dict) -> str:
        return (f'return confirm(\'Keep &quot;{_esc(keep["name"])}&quot; and delete &quot;{_esc(delete["name"])}&quot;? '
                f'This removes it from the public directory.\');')

    # Confirming a duplicate goes straight to "which one do you want to keep"
    # — no separate flag-then-merge step, so a confirmed duplicate can't sit
    # in the directory unresolved. Each row is a live decision: keep A (and
    # delete B), keep B (and delete A), or it's not actually a duplicate.
    def _actionable_row(a: dict, b: dict, normalized_name: str) -> str:
        return f"""<tr>
          <td style="padding:12px;border-bottom:1px solid var(--line);">{_tool_cell(a)}</td>
          <td style="padding:12px;border-bottom:1px solid var(--line);">{_tool_cell(b)}</td>
          <td style="padding:12px;border-bottom:1px solid var(--line);font-size:13px;color:var(--muted);">{_esc(normalized_name)}</td>
          <td style="padding:12px;border-bottom:1px solid var(--line);white-space:nowrap;">
            <form method="post" action="/admin/tools/name-duplicates/merge" style="display:inline;" onsubmit="{_confirm(a, b)}">
              <input type="hidden" name="keep_id" value="{a['id']}">
              <input type="hidden" name="delete_id" value="{b['id']}">
              <button type="submit" class="btn" style="padding:6px 14px;font-size:13px;">Keep &quot;{_esc(a['name'])}&quot;</button>
            </form>
            <form method="post" action="/admin/tools/name-duplicates/merge" style="display:inline;margin-left:6px;" onsubmit="{_confirm(b, a)}">
              <input type="hidden" name="keep_id" value="{b['id']}">
              <input type="hidden" name="delete_id" value="{a['id']}">
              <button type="submit" class="btn" style="padding:6px 14px;font-size:13px;">Keep &quot;{_esc(b['name'])}&quot;</button>
            </form>
            <form method="post" action="/admin/tools/name-duplicates/resolve" style="display:inline;margin-left:6px;">
              <input type="hidden" name="tool_id_a" value="{a['id']}">
              <input type="hidden" name="tool_id_b" value="{b['id']}">
              <button type="submit" class="btn btn-ghost" style="padding:5px 12px;font-size:13px;">Not a duplicate, dismiss</button>
            </form>
          </td>
        </tr>"""

    def _actionable_table(rows: list[dict]) -> str:
        return f"""<div style="overflow-x:auto;">
<table style="width:100%;border-collapse:collapse;background:#fff;border-radius:12px;border:1px solid var(--line);overflow:hidden;">
<thead><tr style="background:var(--accent-light);">
  <th style="padding:10px 12px;text-align:left;font-size:13px;">Tool A</th>
  <th style="padding:10px 12px;text-align:left;font-size:13px;">Tool B</th>
  <th style="padding:10px 12px;text-align:left;font-size:13px;">Normalized name</th>
  <th style="padding:10px 12px;text-align:left;font-size:13px;">Resolve—keep one, or dismiss</th>
</tr></thead>
<tbody>{"".join(_actionable_row(c["tool_a"], c["tool_b"], c["normalized_name"]) for c in rows)}</tbody>
</table>
</div>"""

    pending_html = ""
    if pending_merges:
        pending_html = f"""<h2 style="font-size:16px;font-weight:600;margin:0 0 4px;color:#92400e;">Confirmed duplicates awaiting cleanup</h2>
<p style="color:var(--muted);margin:4px 0 12px;font-size:13px;">Confirmed as a duplicate before this page could delete one for you—still live in the directory. Pick which to keep.</p>
{_actionable_table(pending_merges)}
<div style="margin:32px 0 0;"></div>"""

    if candidates:
        candidates_html = _actionable_table(candidates)
    else:
        candidates_html = ('<div style="background:var(--surface);border:1px solid var(--line);border-radius:12px;'
                           'padding:32px;text-align:center;color:var(--muted);">No unresolved name-duplicate candidates. '
                           'Every exact normalized-name match across all tools has been merged or dismissed.</div>')

    def _decision_row(d: dict) -> str:
        return (f'<tr><td style="padding:8px 12px;border-bottom:1px solid var(--line);font-size:13px;">{_esc(d["name_a"])} &harr; {_esc(d["name_b"])}</td>'
                f'<td style="padding:8px 12px;border-bottom:1px solid var(--line);font-size:13px;"><span style="color:var(--muted);">Dismissed—not a duplicate</span></td>'
                f'<td style="padding:8px 12px;border-bottom:1px solid var(--line);font-size:12px;color:var(--muted);white-space:nowrap;">{_esc(d["created_at"][:10])}</td></tr>')

    decisions_html = ""
    if decisions:
        decisions_html = f"""<h2 style="font-size:16px;font-weight:600;margin:32px 0 12px;">Dismissed—not duplicates</h2>
<div style="overflow-x:auto;">
<table style="width:100%;border-collapse:collapse;background:#fff;border-radius:12px;border:1px solid var(--line);overflow:hidden;">
<tbody>{"".join(_decision_row(d) for d in decisions)}</tbody>
</table>
</div>"""

    body = f"""<div class="page page-admin">
<p style="margin:0 0 4px;"><a href="/admin/tools/software" style="font-size:13px;color:var(--muted);">&larr; Software</a></p>
<h1 style="margin:0 0 4px;">Name-duplicate check</h1>
<p style="color:var(--muted);margin:4px 0 24px;font-size:14px;">
  Exact-match scan of every tool's name (case, parenthetical text, and entity suffixes like Inc/LLC ignored)—catches
  a same-vendor duplicate saved under a different URL, which the URL-based check can't see. Not fuzzy matching:
  spelling or spacing differences won't be flagged here. Confirming a duplicate deletes one right away—pick which
  to keep; nothing lingers half-resolved in the directory.
</p>
{banner}
{pending_html}
{candidates_html}
{decisions_html}
</div>"""
    return HTMLResponse(_page("Name-duplicate check—CFO Toolbox Admin", "", body, authed=True))


@app.post("/admin/tools/name-duplicates/merge")
async def admin_tool_name_duplicates_merge(request: Request):
    if not _is_authed(request):
        raise HTTPException(status_code=401, detail="unauthorized")
    form = await request.form()
    try:
        keep_id = int(form.get("keep_id"))
        delete_id = int(form.get("delete_id"))
    except (TypeError, ValueError):
        raise HTTPException(status_code=400, detail="Invalid tool ids.")
    if keep_id == delete_id:
        raise HTTPException(status_code=400, detail="Keep and delete must be different tools.")
    lib = _lib()
    try:
        keep_tool = lib.get_tool(keep_id)
        delete_tool_row = lib.get_tool(delete_id)
        if not keep_tool or not delete_tool_row:
            raise HTTPException(status_code=404, detail="Tool not found.")
        # delete_tool cascades a cleanup of any tool_name_dedupe_decisions row
        # referencing delete_id, so this pair can never resurface as a
        # candidate or a pending merge — no separate bookkeeping needed here.
        lib.delete_tool(delete_id, admin_id=_current_user_id(lib, request), action="merge")
        msg = f'Kept "{keep_tool["name"]}", deleted duplicate "{delete_tool_row["name"]}".'
    finally:
        lib.close()
    return RedirectResponse(f"/admin/tools/name-duplicates?msg={quote(msg)}", status_code=303)


@app.post("/admin/tools/name-duplicates/resolve")
async def admin_tool_name_duplicates_resolve(request: Request):
    """Only 'not a duplicate' runs through here now — confirming a duplicate
    goes straight to /merge above and deletes immediately, so this route no
    longer accepts a 'duplicate' verdict (that state used to leave a
    confirmed-but-undeleted pair sitting in the directory indefinitely)."""
    if not _is_authed(request):
        raise HTTPException(status_code=401, detail="unauthorized")
    form = await request.form()
    try:
        tool_id_a = int(form.get("tool_id_a"))
        tool_id_b = int(form.get("tool_id_b"))
    except (TypeError, ValueError):
        raise HTTPException(status_code=400, detail="Invalid tool ids.")
    lib = _lib()
    try:
        lib.record_tool_name_dedupe_decision(tool_id_a, tool_id_b, "dismissed")
    finally:
        lib.close()
    msg = "Dismissed—won't resurface."
    return RedirectResponse(f"/admin/tools/name-duplicates?msg={quote(msg)}", status_code=303)


# Field allowlist for the Software bulk-edit panel — server-side gate so a
# crafted request can't write to name/url/description/vendor contact fields,
# which are per-record and excluded from bulk edit by design (see plan).
_SOFTWARE_BULK_FIELDS = {"categories", "advisor", "promoted", "warm_intro_enabled"}


@app.post("/admin/tools/software/bulk-edit")
async def admin_software_bulk_edit(request: Request):
    if not _is_authed(request):
        raise HTTPException(status_code=401, detail="unauthorized")
    payload = await request.json()
    ids = payload.get("ids")
    field = payload.get("field")
    value = payload.get("value")
    if not isinstance(ids, list) or not ids or field not in _SOFTWARE_BULK_FIELDS:
        return JSONResponse({"ok": False, "error": "Invalid request"}, status_code=400)
    lib = _lib()
    try:
        for raw_id in ids:
            try:
                tool_id = int(raw_id)
            except (TypeError, ValueError):
                continue
            t = lib.get_tool(tool_id)
            if not t:
                continue
            kwargs = dict(
                name=t["name"], description=t["description"], url=t["url"],
                categories=t["categories"], advisor=t["advisor"], promoted=t["promoted"],
                vendor_email=t["vendor_email"], warm_intro_enabled=t["warm_intro_enabled"],
                vendor_name=t["vendor_name"], summary=t.get("summary") or "",
            )
            if field == "categories":
                kwargs["categories"] = value if isinstance(value, list) else []
            else:
                kwargs[field] = 1 if value == "1" else 0
            lib.update_tool(tool_id, **kwargs)
    finally:
        lib.close()
    return JSONResponse({"ok": True})


@app.post("/admin/tools/software/bulk-delete-check")
async def admin_software_bulk_delete_check(request: Request):
    """Preview for the Software bulk-delete confirm step: resolves the
    selected ids to names, plus a lightweight (not exhaustive) check for
    whether any of them is curated as a competitor on another tool's
    profile — that tool would silently lose a competitor entry once this
    batch is deleted. tool_competitors is an undirected pair (see the
    CREATE TABLE comment in db.py), so list_tool_competitors(tid) already
    returns both directions; we only flag references from OUTSIDE the
    selection, since two selected tools being mutual competitors isn't a
    surprise to anyone."""
    if not _is_authed(request):
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    payload = await request.json()
    ids = payload.get("ids")
    if not isinstance(ids, list) or not ids:
        return JSONResponse({"ok": False, "error": "Invalid request"}, status_code=400)
    try:
        tool_ids = [int(i) for i in ids]
    except (TypeError, ValueError):
        return JSONResponse({"ok": False, "error": "Invalid request"}, status_code=400)
    selected = set(tool_ids)
    lib = _lib()
    try:
        tools = []
        warnings = []
        for tid in tool_ids:
            t = lib.get_tool(tid)
            if not t:
                continue
            tools.append({"id": tid, "name": t["name"]})
            referencing = [c["name"] for c in lib.list_tool_competitors(tid) if c["id"] not in selected]
            if referencing:
                warnings.append({"name": t["name"], "referenced_by": referencing})
    finally:
        lib.close()
    return JSONResponse({"ok": True, "tools": tools, "warnings": warnings})


@app.post("/admin/tools/software/bulk-delete")
async def admin_software_bulk_delete(request: Request):
    """Same delete path as the single-row Delete button (lib.delete_tool,
    which also cascades field_reviews and tool_competitors rows), just
    looped over the selection made in /admin/tools/software."""
    if not _is_authed(request):
        return JSONResponse({"ok": False, "error": "unauthorized"}, status_code=401)
    payload = await request.json()
    ids = payload.get("ids")
    if not isinstance(ids, list) or not ids:
        return JSONResponse({"ok": False, "error": "Invalid request"}, status_code=400)
    lib = _lib()
    try:
        admin_id = _current_user_id(lib, request)
        for raw_id in ids:
            try:
                tool_id = int(raw_id)
            except (TypeError, ValueError):
                continue
            lib.delete_tool(tool_id, admin_id=admin_id)
    finally:
        lib.close()
    return JSONResponse({"ok": True})


