@app.post("/admin/tools/communities/{community_id}/competitors/add-selected")
async def admin_communities_competitors_add_selected(request: Request, community_id: int):
    """Batch-add version of /competitors/add for Communities—see
    admin_tools_competitors_add_selected for the identical Software pattern
    this mirrors."""
    if not _is_authed(request):
        raise HTTPException(status_code=401, detail="unauthorized")
    lib = _lib()
    try:
        community = lib.get_community(community_id)
        if not community:
            raise HTTPException(status_code=404, detail="Community not found")
        form = await request.form()
        ids = []
        for raw in form.getlist("competitor_id"):
            try:
                ids.append(int(raw))
            except ValueError:
                continue
        for cid in ids:
            if lib.get_community(cid):
                try:
                    lib.add_community_competitor(community_id, cid)
                except ValueError:
                    pass
        _record_ai_drafted_reviews(lib, request, "community", community_id, form)
    finally:
        lib.close()
    return RedirectResponse(f"/tools/communities/{community['slug']}/edit", status_code=303)


@app.post("/admin/tools/communities/{community_id}/competitors/generate-matches")
def admin_communities_generate_competitor_matches(request: Request, community_id: int):
    """AI first pass over suggest_community_competitors' tag-overlap
    shortlist—Communities equivalent of admin_tools_generate_competitor_matches,
    reusing the same generate_competitor_matches() judgment function since the
    underlying task (pick genuine matches from a pre-filtered shortlist) is
    identical for both entity types."""
    if not _is_authed(request):
        raise HTTPException(status_code=401, detail="unauthorized")
    lib = _lib()
    try:
        community = lib.get_community(community_id)
        if not community:
            raise HTTPException(status_code=404, detail="Community not found")
        candidates = lib.suggest_community_competitors(community_id, limit=8)
    finally:
        lib.close()

    from linklib.enrich import generate_competitor_matches
    result = generate_competitor_matches(
        community["name"], community.get("notes", ""),
        [{"id": x["id"], "name": x["name"], "description": x.get("notes", "")} for x in candidates],
    )
    if result is None:
        return JSONResponse({"ok": False, "error": "Generation is unavailable right now "
                                                     "(missing ANTHROPIC_API_KEY, no candidates, or the request failed). "
                                                     "Pick similar communities by hand."}, status_code=503)

    lib = _lib()
    try:
        lib.record_enrichment_cost(None, result.model, result.input_tokens, result.output_tokens, result.cost_usd)
    finally:
        lib.close()

    return JSONResponse({"ok": True, "competitor_ids": result.competitor_ids})


@app.post("/admin/tools/communities/{community_id}/screenshot/recapture")
def admin_communities_screenshot_recapture(request: Request, community_id: int):
    """Communities equivalent of admin_tools_screenshot_recapture (Phase 3b)
    — same synchronous live-capture pattern, own screenshot directory/route
    (see _COMMUNITY_SCREENSHOT_DIR)."""
    if not _is_authed(request):
        raise HTTPException(status_code=401, detail="unauthorized")
    lib = _lib()
    try:
        community = lib.get_community(community_id)
        if not community:
            raise HTTPException(status_code=404, detail="Community not found")
        from linklib.screenshots import capture_homepage
        dest = os.path.join(_COMMUNITY_SCREENSHOT_DIR, f"{community['slug']}.png")
        ok = capture_homepage(community["url"], dest)
        if ok:
            # Absolute, not a bare path: this is what an admin sees and edits
            # in the Screenshot URL field, and a site-relative path there read
            # as unexplained/orphaned ("what is this and why is it here?").
            # See _public_base_url for why the scheme can't just come from
            # request.base_url directly.
            served_url = f"{_public_base_url(request)}/tools/communities/screenshot/{community['slug']}.png?v={int(time.time())}"
            lib.set_community_screenshot_capture(community_id, served_url)
    finally:
        lib.close()
    msg = "screenshot_captured=1" if ok else "screenshot_captured=0"
    return RedirectResponse(f"/tools/communities/{community['slug']}/edit?{msg}", status_code=303)


@app.post("/admin/tools/communities/{community_id}/app-screenshot/recapture")
def admin_communities_app_screenshot_recapture(request: Request, community_id: int):
    """App-screenshot equivalent of admin_communities_screenshot_recapture
    (Phase E) — mirrors admin_tools_app_screenshot_recapture exactly, own
    directory (_COMMUNITY_SCREENSHOT_DIR)."""
    if not _is_authed(request):
        raise HTTPException(status_code=401, detail="unauthorized")
    lib = _lib()
    try:
        community = lib.get_community(community_id)
        if not community:
            raise HTTPException(status_code=404, detail="Community not found")
        source_url = (community.get("app_screenshot_source_url") or "").strip()
        ok = False
        if source_url:
            from linklib.screenshots import capture_homepage
            dest = os.path.join(_COMMUNITY_SCREENSHOT_DIR, f"{community['slug']}-app.png")
            ok = capture_homepage(source_url, dest)
            if ok:
                served_url = f"{_public_base_url(request)}/tools/communities/screenshot/{community['slug']}-app.png?v={int(time.time())}"
                lib.set_community_app_screenshot(community_id, served_url)
    finally:
        lib.close()
    msg = "app_screenshot_captured=1" if ok else "app_screenshot_captured=0"
    return RedirectResponse(f"/tools/communities/{community['slug']}/edit?{msg}", status_code=303)


@app.post("/admin/tools/communities/{community_id}/app-screenshot/upload")
async def admin_communities_app_screenshot_upload(request: Request, community_id: int, file: UploadFile = File(...)):
    """App-screenshot upload equivalent for Communities — mirrors
    admin_tools_app_screenshot_upload exactly."""
    if not _is_authed(request):
        raise HTTPException(status_code=401, detail="unauthorized")
    lib = _lib()
    try:
        community = lib.get_community(community_id)
        if not community:
            raise HTTPException(status_code=404, detail="Community not found")
        data = await file.read()
        ok = len(data) <= _APP_SCREENSHOT_MAX_BYTES and _sniff_image_mime(data) is not None
        if ok:
            dest = os.path.join(_COMMUNITY_SCREENSHOT_DIR, f"{community['slug']}-app.png")
            os.makedirs(os.path.dirname(dest), exist_ok=True)
            with open(dest, "wb") as f:
                f.write(data)
            served_url = f"{_public_base_url(request)}/tools/communities/screenshot/{community['slug']}-app.png?v={int(time.time())}"
            lib.set_community_app_screenshot(community_id, served_url)
    finally:
        lib.close()
    msg = "app_screenshot_captured=1" if ok else "app_screenshot_captured=0"
    return RedirectResponse(f"/tools/communities/{community['slug']}/edit?{msg}", status_code=303)


